    public function fetch_time($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_time(...))($params);
    }

    private function do_fetch_time($params = array()) {
        /**
         * fetches the current integer timestamp in milliseconds from the exchange server
         *
         * @see https://btsecom.github.io/docs/spotV3_3/en/#query-server-time
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {int} the current integer timestamp in milliseconds from the exchange server
         */
        $response = Async\await($this->publicGetSpotApiV33Time($params));
        //
        //     {
        //         "iso" => "2026-02-06T11:48:37.976Z",
        //         "epoch" => 1770378517
        //     }
        //
        return $this->safe_timestamp($response, 'epoch');
    }

    public function fetch_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_markets(...))($params);
    }

    private function do_fetch_markets($params = array()) {
        /**
         * retrieves $data on all $markets for btse
         *
         * @see https://docs.btse.com/markets/rest/get-markets/
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing market $data
         */
        if ($this->options['adjustForTimeDifference'] === true) {
            Async\await($this->load_time_difference());
        }
        $response = Async\await($this->publicGetPublicApiMarketV1Markets($params));
        $data = $this->safe_dict($response, 'data', array());
        $markets = $this->safe_list($data, 'symbols', array());
        return $this->parse_markets($markets);
    }

    public function parse_market(array $market): array {
        //
        // spot
        //     {
        //         "symbol" => "BTC-USDT",
        //         "type" => "Spot",
        //         "category" => "CRYPTO",
        //         "tradeCurrency" => "BTC",
        //         "baseCurrency" => "BTC",
        //         "quoteCurrency" => "USDT",
        //         "displayName" => "Bitcoin",
        //         "active" => true,
        //         "minOrderPrice" => "0.1",
        //         "minPriceIncrement" => "0.1",
        //         "pricePrecision" => 1,
        //         "minOrderSize" => "0.00001",
        //         "maxOrderSize" => "100",
        //         "minSizeIncrement" => "0.00001",
        //         "sizePrecision" => 5
        //     }
        //
        // swap
        //     {
        //         "symbol" => "BTC-PERP-USDT",
        //         "type" => "FuturesPerpetual",
        //         "category" => "CRYPTO",
        //         "tradeCurrency" => "BTC-PERP",
        //         "baseCurrency" => "BTC",
        //         "quoteCurrency" => "USDT",
        //         "displayName" => "Bitcoin",
        //         "active" => true,
        //         "minOrderPrice" => "0.1",
        //         "minPriceIncrement" => "0.1",
        //         "pricePrecision" => 1,
        //         "minOrderSize" => "1",
        //         "maxOrderSize" => "7500000",
        //         "minSizeIncrement" => "1",
        //         "sizePrecision" => 0,
        //         "contractSize" => "0.00001",
        //         "availableSettlement" => array( "USD", "USDT" )
        //     }
        //
        // future
        //     {
        //         "symbol" => "BTC-260925-USDT",
        //         "type" => "FuturesTimeBased",
        //         "category" => "CRYPTO",
        //         "tradeCurrency" => "BTC-260925",
        //         "baseCurrency" => "BTC",
        //         "quoteCurrency" => "USDT",
        //         "displayName" => "Bitcoin",
        //         "active" => true,
        //         "minOrderPrice" => "0.1",
        //         "minPriceIncrement" => "0.1",
        //         "pricePrecision" => 1,
        //         "minOrderSize" => "1",
        //         "maxOrderSize" => "100000",
        //         "minSizeIncrement" => "1",
        //         "sizePrecision" => 0,
        //         "contractSize" => "0.00001",
        //         "availableSettlement" => array( "USD", "USDT" ),
        //         "contractStartTime" => 1774569600000,
        //         "contractEndTime" => 1790323230000,
        //         "matchingStartTime" => 1774569615000,
        //         "becomeInactiveTime" => 1790323200000
        //     }
        //
        $marketType = $this->safe_string($market, 'type');
        $isSpot = $marketType === 'Spot';
        $isFuture = $marketType === 'FuturesTimeBased';
        $isSwap = $marketType === 'FuturesPerpetual';
        $id = $this->safe_string($market, 'symbol');
        $baseId = $this->safe_string($market, 'baseCurrency');
        $quoteId = $this->safe_string($market, 'quoteCurrency');
        $base = $this->safe_currency_code($baseId);
        $quote = $this->safe_currency_code($quoteId);
        $symbol = $base . '/' . $quote;
        $maxAmountString = $this->safe_string($market, 'maxOrderSize');
        $minAmountString = $this->safe_string($market, 'minOrderSize');
        $minPriceString = $this->safe_string($market, 'minOrderPrice');
        $pricePrecision = $this->safe_string($market, 'minPriceIncrement');
        $amountPrecision = $this->safe_string($market, 'minSizeIncrement');
        $active = $this->safe_bool($market, 'active');
        $type = 'spot';
        $expiry = null;
        $contractSize = null;
        if (!$isSpot) {
            $symbol .= ':' . $quote;
            $contractSize = $this->safe_string($market, 'contractSize');
            if ($isFuture) {
                $expiry = $this->safe_integer($market, 'contractEndTime');
                $symbol .= '-' . $this->yymmdd($expiry);
                $type = 'future';
            } else {
                $type = 'swap';
            }
        }
        $fees = $this->safe_value($this->fees, 'contract');
        if ($isSpot) {
            $fees = $this->safe_value($this->fees, 'spot');
        }
        return $this->safe_market_structure(array(
            'id' => $id,
            'symbol' => $symbol,
            'base' => $base,
            'quote' => $quote,
            'settle' => $isSpot ? null : $quote,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'settleId' => $isSpot ? null : $quoteId,
            'type' => $type,
            'spot' => $isSpot,
            'margin' => $isSpot ? false : null,
            'swap' => $isSwap,
            'future' => $isFuture,
            'option' => false,
            'active' => $active,
            'contract' => $isSwap || $isFuture,
            'linear' => $isSpot ? null : true,
            'inverse' => $isSpot ? null : false,
            'taker' => $fees['taker'],
            'maker' => $fees['maker'],
            'contractSize' => $this->parse_number($contractSize),
            'expiry' => $expiry,
            'expiryDatetime' => $this->iso8601($expiry),
            'strike' => null,
            'optionType' => null,
            'precision' => array(
                'amount' => $this->parse_number($amountPrecision),
                'price' => $this->parse_number($pricePrecision),
            ),
            'limits' => array(
                'leverage' => array(
                    'min' => null,
                    'max' => null,
                ),
                'amount' => array(
                    'min' => $this->parse_number($minAmountString),
                    'max' => $this->parse_number($maxAmountString),
                ),
                'price' => array(
                    'min' => $this->parse_number($minPriceString),
                    'max' => null,
                ),
                'cost' => array(
                    'min' => null,
                    'max' => null,
                ),
            ),
            'created' => null,
            'info' => $market,
        ));
    }

    public function fetch_ohlcv(string $symbol, $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ohlcv(...))($symbol, $timeframe, $since, $limit, $params);
    }

    private function do_fetch_ohlcv(string $symbol, $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical candlestick $data containing the open, high, low, and close price, and the volume of a $market
         *
         * @see https://docs.btse.com/markets/rest/get-klines/
         *
         * @param {string} $symbol unified $symbol of the $market to fetch OHLCV $data for
         * @param {string} $timeframe the length of time each candle represents
         * @param {int} [$since] timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum amount of candles to fetch (default and max 300)
         * @param {array} [$params] extra parameters specific to the bitteam api endpoint
         * @param {int} [$params->until] timestamp in ms of the latest candle to fetch
         * @param {boolean} [$params->paginate] default false, when true will automatically $paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-$params)
         * @return {int[][]} A list of candles ordered, open, high, low, close, volume
         */
        Async\await($this->load_markets());
        $maxLimit = 300;
        $paginate = false;
        list($paginate, $params) = $this->handle_option_and_params($params, 'fetchOHLCV', 'paginate');
        if ($paginate) {
            return $this->fetch_paginated_call_deterministic('fetchOHLCV', $symbol, $since, $limit, $timeframe, $params, $maxLimit);
        }
        $market = $this->market($symbol);
        $interval = $this->safe_string($this->timeframes, $timeframe, $timeframe);
        $request = array(
            'symbol' => $market['id'],
            'resolution' => $interval,
        );
        if ($limit !== null) {
            $request['limit'] = min($limit, $maxLimit);
        } else {
            // the endpoint returns only 10 candles when the $limit is omitted
            $request['limit'] = $maxLimit;
        }
        if ($since !== null) {
            // the endpoint accepts timestamps in seconds
            $request['start'] = $this->parse_to_int($since / 1000);
        }
        $until = null;
        list($until, $params) = $this->handle_option_and_params($params, 'fetchOHLCV', 'until');
        if ($until !== null) {
            if ($since !== null) {
                // check if the requested time range is too large for one $request
                // if so, just omit $until for correct paginated calls for not to get an error from the exchange
                $duration = $this->parse_timeframe($timeframe);
                $maxDelta = $duration * $maxLimit * 1000; // parseTimeframe returns seconds, the $difference below is in milliseconds
                $difference = $until - $since;
                if ($difference < $maxDelta) {
                    $request['end'] = $this->parse_to_int($until / 1000);
                }
            } else {
                $request['end'] = $this->parse_to_int($until / 1000);
            }
        }
        $response = Async\await($this->publicGetPublicApiMarketV1Klines($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             array(
        //                 "1786600800",
        //                 "1895.78",
        //                 "1898.52",
        //                 "1892.05",
        //                 "1898.3",
        //                 "560622.306372"
        //             )
        //         ),
        //         "code" => 1,
        //         "msg" => "Success",
        //         "success" => true,
        //         "time" => 1786604274378
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        $result = $this->parse_ohlcvs($data, $market, $timeframe, $since, $limit);
        return $result;
    }

    public function parse_ohlcv(mixed $ohlcv, ?array $market = null): array {
        //
        //     array(
        //         "1786600800", // timestamp in seconds
        //         "1895.78",
        //         "1898.52",
        //         "1892.05",
        //         "1898.3",
        //         "560622.306372" // volume in quote currency, contract rows may use scientific notation
        //     )
        //
        return array(
            $this->safe_timestamp($ohlcv, 0),
            $this->safe_number($ohlcv, 1),
            $this->safe_number($ohlcv, 2),
            $this->safe_number($ohlcv, 3),
            $this->safe_number($ohlcv, 4),
            $this->safe_number($ohlcv, 5),
        );
    }

    public function fetch_order_book(string $symbol, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order_book(...))($symbol, $limit, $params);
    }

    private function do_fetch_order_book(string $symbol, ?int $limit = null, $params = array()) {
        /**
         * fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other $data
         *
         * @see https://docs.btse.com/markets/rest/get-orderbook/
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] the maximum amount of order book entries to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} A dictionary of {@link https://github.com/ccxt/ccxt/wiki/Manual#order-book-structure order book structures} indexed by $market symbols
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        if ($limit !== null) {
            $request['depth'] = min($limit, 50); // the endpoint supports a maximum depth of 50
        }
        $response = Async\await($this->publicGetPublicApiMarketV1Orderbook($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             "timestamp" => 1786605670799,
        //             "bids" => array(
        //                 array( "1896.11", "0.015" )
        //             ),
        //             "asks" => array(
        //                 array( "1896.74", "0.945" )
        //             )
        //         ),
        //         "code" => 1,
        //         "msg" => "Success",
        //         "success" => true,
        //         "time" => 1786605670833
        //     }
        //
        $data = $this->safe_dict($response, 'data', array());
        $timestamp = $this->safe_integer($data, 'timestamp');
        return $this->parse_order_book($data, $market['symbol'], $timestamp, 'bids', 'asks');
    }

    public function fetch_funding_rate_history(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_funding_rate_history(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_funding_rate_history(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical funding $rate prices
         *
         * @see https://docs.btse.com/markets/rest/get-funding-$rate-history/
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the funding $rate history for
         * @param {int} [$since] $timestamp in ms of the earliest funding $rate to fetch, used to select the requested $period and then applied client-side
         * @param {int} [$limit] the maximum amount of entries to fetch, applied client-side
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->period] the funding $rate history $period, one of '7D', '2W' or '1M', selected from $since by default
         * @param {int} [$params->until] $timestamp in ms of the latest funding $rate to fetch, applied client-side
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=funding-$rate-history-structure funding $rate structures~
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' fetchFundingRateHistory() requires a $symbol argument');
        }
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        if ($market['contract'] !== true) {
            throw new BadRequest($this->id . ' fetchFundingRateHistory() supports contract markets only');
        }
        $period = null;
        list($period, $params) = $this->handle_option_and_params($params, 'fetchFundingRateHistory', 'period');
        if ($period === null) {
            $period = '7D';
            if ($since !== null) {
                $age = $this->milliseconds() - $since;
                $day = 86400000;
                if ($age > 14 * $day) {
                    $period = '1M';
                } elseif ($age > 7 * $day) {
                    $period = '2W';
                }
            }
        }
        $request = array(
            'symbol' => $market['id'],
            'period' => $period,
        );
        $until = null;
        list($until, $params) = $this->handle_option_and_params($params, 'fetchFundingRateHistory', 'until');
        $response = Async\await($this->publicGetPublicApiMarketV1RecentFundingHistory($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             {
        //                 "timestamp" => 1786003200911,
        //                 "rate" => "0.0000152"
        //             }
        //         ),
        //         "code" => 1,
        //         "msg" => "Success",
        //         "success" => true,
        //         "time" => 1786607775380
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        $rates = $this->parse_funding_rate_histories($data, $market, $since, $limit);
        if ($until === null) {
            return $rates;
        }
        $result = array();
        for ($i = 0; $i < count($rates); $i++) {
            $rate = $rates[$i];
            $timestamp = $this->safe_integer($rate, 'timestamp');
            if (($timestamp === null) || ($timestamp <= $until)) {
                $result[] = $rate;
            }
        }
        return $result;
    }

    public function parse_funding_rate_history(mixed $contract, ?array $market = null) {
        //
        //     {
        //         "timestamp" => 1786003200911,
        //         "rate" => "0.0000152"
        //     }
        //
        $timestamp = $this->safe_integer($contract, 'timestamp');
        return array(
            'info' => $contract,
            'symbol' => $this->safe_symbol(null, $market),
            'fundingRate' => $this->safe_number($contract, 'rate'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
        );
    }

    public function fetch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_balance(...))($params);
    }

    private function do_fetch_balance($params = array()) {
        /**
         * query for balance and get the amount of funds available for trading or funds locked in orders
         *
         * @see https://docs.btse.com/wallet/rest/get-user-assets/
         * @see https://btsecom.github.io/docs/futuresV2_3/en/#query-$wallet-balance
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->type] $wallet $type, spot or swap, default is spot
         * @param {string} [$params->wallet] futures $wallet name, CROSS@ by default, or ISOLATED@ followed by the market id with -USDT appended
         * @return {array} a ~@link https://docs.ccxt.com/?id=balance-structure balance structure~
         */
        Async\await($this->load_markets());
        $type = 'spot';
        list($type, $params) = $this->handle_market_type_and_params('fetchBalance', null, $params, $type);
        $response = null;
        if ($type === 'spot') {
            $walletResponse = Async\await($this->privateGetPublicApiWalletV1UserAssets($params));
            //
            //     {
            //         "data" => array(
            //             {
            //                 "asset" => "BTC",
            //                 "type" => "CRYPTO",
            //                 "totalAmount" => "100.0",
            //                 "availableAmount" => "100.0",
            //                 "availableActions" => array( "CONVERT", "TRANSFER", "WITHDRAW", "DEPOSIT", "SEND_TO" ),
            //                 "cryptoNetwork" => array( "depositNetworks" => array( "BITCOIN" ), "withdrawalNetworks" => array( "BITCOIN" ) )
            //             }
            //         ),
            //         "code" => 1,
            //         "msg" => "Success",
            //         "success" => true,
            //         "time" => 1624989977940
            //     }
            //
            $response = $this->safe_list($walletResponse, 'data', array());
        } else {
            $wallet = null;
            list($wallet, $params) = $this->handle_option_and_params($params, 'fetchBalance', 'wallet', 'CROSS@');
            $request = array(
                'wallet' => $wallet,
            );
            $response = Async\await($this->privateGetFuturesApiV23UserWallet($this->extend($request, $params)));
            //
            //     array(
            //         {
            //             "wallet" => "CROSS@",
            //             "totalValue" => 100,
            //             "marginBalance" => 100,
            //             "availableBalance" => 100,
            //             "unrealisedProfitLoss" => 0,
            //             "assets" => array(
            //                 array("balance" => 0.20183537, "assetPrice" => 7158.844999999999, "currency" => "BTC")
            //             ),
            //             "assetsInUse" => array(
            //                 array("balance" => 0.01, "assetPrice" => 7158.844999999999, "currency" => "BTC")
            //             )
            //         }
            //     )
            //
        }
        return $this->parse_balance($response);
    }

    public function parse_balance(mixed $response): array {
        $result = array(
            'info' => $response,
        );
        $totals = array();
        $frees = array();
        $useds = array();
        for ($i = 0; $i < count($response); $i++) {
            $row = $response[$i];
            $assets = $this->safe_list($row, 'assets');
            if ($assets !== null) {
                // futures wallet $row => per-currency $totals in $assets, locked amounts in assetsInUse
                // several wallet rows can report the same currency, so amounts are aggregated
                $inUse = $this->safe_list($row, 'assetsInUse', array());
                for ($j = 0; $j < count($inUse); $j++) {
                    $usedRow = $inUse[$j];
                    $usedCode = $this->safe_currency_code($this->safe_string($usedRow, 'currency'));
                    if ($usedCode === null) {
                        continue;
                    }
                    $useds[$usedCode] = Precise::string_add($this->safe_string($useds, $usedCode, '0'), $this->safe_string($usedRow, 'balance'));
                }
                for ($j = 0; $j < count($assets); $j++) {
                    $assetRow = $assets[$j];
                    $code = $this->safe_currency_code($this->safe_string($assetRow, 'currency'));
                    if ($code === null) {
                        continue;
                    }
                    $totals[$code] = Precise::string_add($this->safe_string($totals, $code, '0'), $this->safe_string($assetRow, 'balance'));
                    $useds[$code] = $this->safe_string($useds, $code, '0');
                }
            } else {
                // unified wallet $row => array("asset" => "BTC", "totalAmount" => "100.0", "availableAmount" => "100.0")
                // legacy spot wallet $row => array("available" => 520.52, "currency" => "USD", "total" => 5566.5566)
                $code = $this->safe_currency_code($this->safe_string_2($row, 'asset', 'currency'));
                if ($code === null) {
                    continue;
                }
                $totals[$code] = Precise::string_add($this->safe_string($totals, $code, '0'), $this->safe_string_2($row, 'totalAmount', 'total'));
                $frees[$code] = Precise::string_add($this->safe_string($frees, $code, '0'), $this->safe_string_2($row, 'availableAmount', 'available'));
            }
        }
        $codes = is_array($totals) ? array_keys($totals) : array();
        for ($i = 0; $i < count($codes); $i++) {
            $code = $codes[$i];
            $account = $this->account();
            $account['total'] = $this->safe_string($totals, $code);
            $account['free'] = $this->safe_string($frees, $code);
            $account['used'] = $this->safe_string($useds, $code);
            $result[$code] = $account;
        }
        return $this->safe_balance($result);
    }

    public function fetch_leverage_tiers(?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_leverage_tiers(...))($symbols, $params);
    }

    private function do_fetch_leverage_tiers(?array $symbols = null, $params = array()) {
        /**
         *
         * @see https://docs.btse.com/markets/rest/get-$market-risk-limits/
         *
         * retrieve information on the maximum leverage, for different trade sizes
         * @param {string[]|null} $symbols a list of unified $market $symbols
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/?id=leverage-$tiers-structure leverage $tiers structures~, indexed by $market $symbols
         */
        Async\await($this->load_markets());
        $symbols = $this->market_symbols($symbols);
        $request = array();
        if ($symbols !== null) {
            $length = count($symbols);
            if ($length === 1) {
                $requestedSymbol = $this->safe_string($symbols, 0);
                $market = $this->market($requestedSymbol);
                $request['symbol'] = $market['id'];
            }
        }
        $response = Async\await($this->publicGetPublicApiMarketV1RiskLimits($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             {
        //                 "symbol" => "BTC-PERP-USDT",
        //                 "riskLimits" => array(
        //                     array( "level" => 1, "value" => 3000000 ),
        //                     array( "level" => 2, "value" => 6000000 )
        //                 )
        //             }
        //         ),
        //         "code" => 1,
        //         "msg" => "Success",
        //         "success" => true,
        //         "time" => 1786609503920
        //     }
        //
        // a $single-$symbol $request returns the $entry directly in $data
        //
        $data = $this->safe_list($response, 'data');
        if ($data === null) {
            $single = $this->safe_dict($response, 'data', array());
            $data = array( $single );
        }
        $result = array();
        for ($i = 0; $i < count($data); $i++) {
            $entry = $data[$i];
            $marketId = $this->safe_string($entry, 'symbol');
            $market = $this->safe_market($marketId);
            $symbol = $market['symbol'];
            if ($symbols === null || $this->in_array($symbol, $symbols)) {
                $levels = $this->safe_list($entry, 'riskLimits', array());
                $tiers = array();
                for ($j = 0; $j < count($levels); $j++) {
                    $level = $levels[$j];
                    // the endpoint only reports the notional ladder, the
                    // per-tier leverage and margin rates are not available
                    $tiers[] = array(
                        'tier' => $this->safe_integer($level, 'level'),
                        'symbol' => $symbol,
                        'currency' => $market['settle'],
                        'minNotional' => null,
                        'maxNotional' => $this->safe_number($level, 'value'),
                        'maintenanceMarginRate' => null,
                        'maxLeverage' => null,
                        'info' => $level,
                    );
                }
                $result[$symbol] = $tiers; // rows arrive ordered by $level ascending, avoid sortBy which compares numeric keys lexicographically in some transpiled runtimes
            }
        }
        // the exchange only provides the cap of each risk tier, so the floor
        // is derived from the previous tier => 0 for the first tier, and the
        // previous tier's maxNotional for every subsequent tier
        $symbolKeys = is_array($result) ? array_keys($result) : array();
        for ($i = 0; $i < count($symbolKeys); $i++) {
            $symbolKey = $symbolKeys[$i];
            $tiersList = $result[$symbolKey];
            for ($j = 0; $j < count($tiersList); $j++) {
                if ($j === 0) {
                    $tiersList[$j]['minNotional'] = 0;
                } else {
                    $tiersList[$j]['minNotional'] = $tiersList[$j - 1]['maxNotional'];
                }
            }
            // php copies arrays by value, so the mutated list must be written back explicitly
            $result[$symbolKey] = $tiersList;
        }
        return $result;
    }

    public function fetch_market_leverage_tiers(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_market_leverage_tiers(...))($symbol, $params);
    }

    private function do_fetch_market_leverage_tiers(string $symbol, $params = array()) {
        /**
         * retrieve information on the maximum leverage, for different trade sizes for a single $market
         *
         * @see https://docs.btse.com/markets/rest/get-$market-risk-limits/
         *
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=leverage-tiers-structure leverage tiers structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        if ($market['contract'] !== true) {
            throw new BadRequest($this->id . ' fetchMarketLeverageTiers() supports contract markets only');
        }
        $result = Async\await($this->fetch_leverage_tiers(array( $symbol ), $params));
        return $result[$symbol];
    }

    public function fetch_tickers(?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_tickers(...))($symbols, $params);
    }

    private function do_fetch_tickers(?array $symbols = null, $params = array()) {
        /**
         *
         * @see https://docs.btse.com/markets/rest/get-24-hr-ticker/
         *
         * fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
         * @param {string[]|null} $symbols unified $symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/?id=ticker-structure ticker structures~
         */
        Async\await($this->load_markets());
        $symbols = $this->market_symbols($symbols, null, true, true);
        // the unified endpoint serves all market types in one call, the legacy type param is accepted and ignored
        $params = $this->omit($params, 'type');
        $response = Async\await($this->publicGetPublicApiMarketV1Ticker24hr($params));
        $data = $this->safe_list($response, 'data', array());
        return $this->parse_tickers($data, $symbols);
    }

    public function fetch_ticker(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ticker(...))($symbol, $params);
    }

    private function do_fetch_ticker(string $symbol, $params = array()) {
        /**
         * fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific $market
         *
         * @see https://docs.btse.com/markets/rest/get-24-hr-ticker/
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the ticker for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=ticker-structure ticker structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        $response = Async\await($this->publicGetPublicApiMarketV1Ticker24hr($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             {
        //                 "symbol" => "BTC-PERP-USDT",
        //                 "lastPrice" => "63790.1",
        //                 "openPrice" => "63808.3",
        //                 "highPrice" => "64446.7",
        //                 "lowPrice" => "63289.7",
        //                 "amount" => "789198764",
        //                 "volume" => "502595131.844331",
        //                 "openTime" => 1786514400,
        //                 "closeTime" => 1786602644,
        //                 "priceChange" => "-18.2",
        //                 "priceChangePercent" => "0",
        //                 "prevClosePrice" => "63842.4",
        //                 "bidPrice" => "63790",
        //                 "bidQty" => "222000",
        //                 "askPrice" => "63790.2",
        //                 "askQty" => "255355",
        //                 "openInterest" => "29489680",
        //                 "fundingRate" => "0.0001",
        //                 "nextFundingTime" => 1786608000000,
        //                 "fundingIntervalMinutes" => 480
        //             }
        //         ),
        //         "code" => 1,
        //         "msg" => "Success",
        //         "success" => true,
        //         "time" => 1786602644221
        //     }
        //
        // a single-$symbol query returns $data object, a multi-$symbol or bare query returns an array
        $data = $this->safe_dict($response, 'data');
        if ($data === null) {
            $rows = $this->safe_list($response, 'data', array());
            $data = $this->safe_dict($rows, 0, array());
        }
        return $this->parse_ticker($data, $market);
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        //
        // spot rows carry the fields up to askQty, contract rows additionally carry
        // openInterest, fundingRate, nextFundingTime and fundingIntervalMinutes
        //
        $marketId = $this->safe_string($ticker, 'symbol');
        $market = $this->safe_market($marketId, $market);
        $last = $this->safe_string($ticker, 'lastPrice');
        $baseVolume = $this->safe_string($ticker, 'amount');
        if (($baseVolume !== null) && ($market !== null) && ($market['contract'] === true)) {
            // for contract markets the amount field is denominated in contracts, verified live -
            // scaling by contractSize converts it into base currency units
            $contractSizeString = $this->number_to_string($market['contractSize']);
            if ($contractSizeString !== null) {
                $baseVolume = Precise::string_mul($baseVolume, $contractSizeString);
            }
        }
        $timestamp = $this->safe_timestamp($ticker, 'closeTime');
        return $this->safe_ticker(array(
            'symbol' => $this->safe_symbol($marketId, $market),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => $this->safe_string($ticker, 'highPrice'),
            'low' => $this->safe_string($ticker, 'lowPrice'),
            'bid' => $this->safe_string($ticker, 'bidPrice'),
            'bidVolume' => $this->safe_string($ticker, 'bidQty'),
            'ask' => $this->safe_string($ticker, 'askPrice'),
            'askVolume' => $this->safe_string($ticker, 'askQty'),
            'vwap' => null,
            'open' => $this->safe_string($ticker, 'openPrice'),
            'close' => $last,
            'last' => $last,
            'previousClose' => $this->safe_string($ticker, 'prevClosePrice'),
            'change' => $this->safe_string($ticker, 'priceChange'),
            // priceChangePercent is a ratio rounded to three decimals, not a percentage,
            // so it is left out and safeTicker derives percentage from change and open
            'percentage' => null,
            'average' => null,
            'baseVolume' => $baseVolume,
            'quoteVolume' => $this->safe_string($ticker, 'volume'),
            'markPrice' => null,
            'indexPrice' => null,
            'info' => $ticker,
        ), $market);
    }

    public function fetch_open_interest(string $symbol, $params = array()) {
        return Async\async(self::do_fetch_open_interest(...))($symbol, $params);
    }

    private function do_fetch_open_interest(string $symbol, $params = array()) {
        /**
         * Retrieves the open $interest of a derivative trading pair
         *
         * @see https://docs.btse.com/markets/rest/get-24-hr-ticker/
         *
         * @param {string} $symbol Unified CCXT $market $symbol
         * @param {array} [$params] exchange specific parameters
         * @return {array} an open $interest structurearray(@link https://docs.ccxt.com/?id=$interest-history-structure)
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        if ($market['spot'] === true) {
            throw new BadRequest($this->id . ' fetchOpenInterest() $symbol does not support $market ' . $symbol);
        }
        $request = array(
            'symbol' => $market['id'],
        );
        $response = Async\await($this->publicGetPublicApiMarketV1Ticker24hr($this->extend($request, $params)));
        $interest = $this->safe_dict($response, 'data');
        if ($interest === null) {
            $rows = $this->safe_list($response, 'data', array());
            $interest = $this->safe_dict($rows, 0, array());
        }
        return $this->parse_open_interest($interest, $market);
    }

    public function fetch_open_interests(?array $symbols = null, $params = array()) {
        return Async\async(self::do_fetch_open_interests(...))($symbols, $params);
    }

    private function do_fetch_open_interests(?array $symbols = null, $params = array()) {
        /**
         * Retrieves the open interest for a list of $symbols
         *
         * @see https://docs.btse.com/markets/rest/get-24-hr-ticker/
         *
         * @param {string[]} [$symbols] a list of unified CCXT market $symbols
         * @param {array} [$params] exchange specific parameters
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=open-interest-structure open interest structures~
         */
        Async\await($this->load_markets());
        $symbols = $this->market_symbols($symbols);
        $response = Async\await($this->publicGetPublicApiMarketV1Ticker24hr($params));
        $data = $this->safe_list($response, 'data', array());
        $rows = array();
        for ($i = 0; $i < count($data); $i++) {
            $row = $data[$i];
            // spot $rows do not carry an open interest
            if ($this->safe_string($row, 'openInterest') !== null) {
                $rows[] = $row;
            }
        }
        return $this->parse_open_interests($rows, $symbols);
    }

    public function parse_open_interest(mixed $interest, ?array $market = null) {
        //
        // ticker/24hr contract rows, see parseFundingRate for the full shape
        //
        $marketId = $this->safe_string($interest, 'symbol');
        $market = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_timestamp($interest, 'closeTime');
        return $this->safe_open_interest(array(
            'symbol' => $market['symbol'],
            'openInterestAmount' => $this->safe_number($interest, 'openInterest'),
            'openInterestValue' => $this->safe_number($interest, 'openInterestUSD'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'info' => $interest,
        ), $market);
    }

