    private function do_fetch_funding_rates(?array $symbols = null, $params = array()) {
        /**
         * fetch the funding rate for multiple markets
         *
         * @see https://docs.btse.com/markets/rest/get-24-hr-ticker/
         *
         * @param {string[]|null} $symbols list of unified market $symbols
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=funding-rates-structure funding rates structures~, indexe by market $symbols
         */
        Async\await($this->load_markets());
        $symbols = $this->market_symbols($symbols);
        $response = Async\await($this->publicGetPublicApiMarketV1Ticker24hr($params));
        $data = $this->safe_list($response, 'data', array());
        $rows = array();
        for ($i = 0; $i < count($data); $i++) {
            $row = $data[$i];
            // spot $rows do not carry a funding rate
            if ($this->safe_string($row, 'fundingRate') !== null) {
                $rows[] = $row;
            }
        }
        return $this->parse_funding_rates($rows, $symbols);
    }

    public function parse_funding_rate(mixed $contract, ?array $market = null): array {
        //
        // ticker/24hr $contract rows
        //     {
        //         "symbol" => "ETH-PERP-USDT",
        //         "lastPrice" => "1896.17",
        //         "openPrice" => "1887.07",
        //         "highPrice" => "1924",
        //         "lowPrice" => "1872.44",
        //         "amount" => "1937140691",
        //         "volume" => "366459222.269293",
        //         "openTime" => 1786518000,
        //         "closeTime" => 1786607054,
        //         "priceChange" => "9.1",
        //         "priceChangePercent" => "0.005",
        //         "prevClosePrice" => "1897.71",
        //         "bidPrice" => "1896",
        //         "bidQty" => "105",
        //         "askPrice" => "1896.01",
        //         "askQty" => "11354",
        //         "openInterest" => "19344237",
        //         "fundingRate" => "0.00006016",
        //         "nextFundingTime" => 1786608000000,
        //         "fundingIntervalMinutes" => 480
        //     }
        //
        $marketId = $this->safe_string($contract, 'symbol');
        $market = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_timestamp($contract, 'closeTime');
        // dated futures carry a zero nextFundingTime only applies to
        // perpetuals, observed live, the zero means no next funding and is omitted
        $nextFundingTimestamp = $this->safe_integer_omit_zero($contract, 'nextFundingTime');
        $fundingIntervalMinutes = $this->safe_integer($contract, 'fundingIntervalMinutes');
        $interval = null;
        if ($fundingIntervalMinutes !== null) {
            $hours = $this->parse_to_int($fundingIntervalMinutes / 60);
            $interval = (string) $hours . 'h';
        }
        return array(
            'info' => $contract,
            'symbol' => $market['symbol'],
            'markPrice' => null,
            'indexPrice' => null,
            'interestRate' => null,
            'estimatedSettlePrice' => null,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'fundingRate' => $this->safe_number($contract, 'fundingRate'),
            'fundingTimestamp' => null,
            'fundingDatetime' => null,
            'nextFundingRate' => null,
            'nextFundingTimestamp' => $nextFundingTimestamp,
            'nextFundingDatetime' => $this->iso8601($nextFundingTimestamp),
            'previousFundingRate' => null,
            'previousFundingTimestamp' => null,
            'previousFundingDatetime' => null,
            'interval' => $interval,
        );
    }

    public function fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * get the list of most recent $trades for a particular $symbol
         *
         * @see https://docs.btse.com/markets/rest/get-trades/
         *
         * @param {string} $symbol unified $symbol of the $market to fetch $trades for
         * @param {int} [$since] $timestamp in ms of the earliest $trade to fetch, applied client-side to the most recent $trades window
         * @param {int} [$limit] the maximum amount of $trades to fetch (max 500)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] $timestamp in ms of the latest entry to fetch, applied client-side to the most recent $trades window
         * @return {Trade[]} a list of ~@link https://docs.ccxt.com/?id=public-$trades $trade structures~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        if ($limit !== null) {
            $request['limit'] = min($limit, 500); // the endpoint supports a maximum of 500 $trades
        }
        // the unified $trades endpoint has no server-side time filtering, $since and $until are applied client-side below
        $until = null;
        list($until, $params) = $this->handle_option_and_params($params, 'fetchTrades', 'until');
        $response = Async\await($this->publicGetPublicApiMarketV1Trades($this->extend($request, $params)));
        //
        //     {
        //         "data" => array(
        //             {
        //                 "id" => 91151062,
        //                 "timestamp" => 1786605669577,
        //                 "price" => "1896.3291755587",
        //                 "size" => "0.06",
        //                 "quoteSize" => "113.7797505335",
        //                 "side" => "BUY"
        //             }
        //         ),
        //         "code" => 1,
        //         "msg" => "Success",
        //         "success" => true,
        //         "time" => 1786605671650
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        $trades = $this->parse_trades($data, $market, $since, $limit);
        if ($until === null) {
            return $trades;
        }
        $result = array();
        for ($i = 0; $i < count($trades); $i++) {
            $trade = $trades[$i];
            $timestamp = $this->safe_integer($trade, 'timestamp');
            if (($timestamp === null) || ($timestamp <= $until)) {
                $result[] = $trade;
            }
        }
        return $result;
    }

    public function fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_my_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch all trades made by the user
         *
         * @see https://docs.btse.com/spot/rest/get-trade-history/
         * @see https://docs.btse.com/futures/rest/get-trade-history/
         *
         * @param {string} [$symbol] unified $market $symbol
         * @param {int} [$since] the earliest time in ms to fetch trades for
         * @param {int} [$limit] the maximum number of trades structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms for the ending date filter, default is null
         * @param {string} [$params->type] 'spot' or 'swap' or 'future', default is 'spot'
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=trade-structure trade structures~
         */
        Async\await($this->load_markets());
        $paginate = $this->safe_bool($params, 'paginate', false);
        if ($paginate === true) {
            $params = $this->omit($params, 'paginate');
            return Async\await($this->fetch_paginated_call_dynamic('fetchMyTrades', $symbol, $since, $limit, $params));
        }
        $market = null;
        $request = array();
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $request['symbol'] = $market['id'];
        }
        if ($since !== null) {
            $request['startTime'] = $since;
        }
        if ($limit !== null) {
            $request['count'] = $limit;
        }
        list($request, $params) = $this->handle_until_option('endTime', $request, $params);
        $marketType = 'spot';
        list($marketType, $params) = $this->handle_market_type_and_params('fetchMyTrades', $market, $params, $marketType);
        $response = null;
        if ($marketType === 'spot') {
            if ($symbol === null) {
                throw new ArgumentsRequired($this->id . ' fetchMyTrades() requires a $symbol argument for spot markets');
            }
            //
            //     {
            //         "data" => array(
            //             {
            //                 "serialId" => 375599088,
            //                 "tradeId" => "de1a79b8-f408-4e05-b8b7-7ed3c4e86542",
            //                 "orderId" => "6c72d906-cb8f-469c-8ab0-b97bc8dff9c2",
            //                 "clOrderId" => null,
            //                 "symbol" => "BTC-USD",
            //                 "base" => "BTC",
            //                 "quote" => "USD",
            //                 "orderSide" => "BUY",
            //                 "orderType" => 77,
            //                 "triggerType" => 0,
            //                 "triggerPrice" => 0,
            //                 "price" => 64235.97008,
            //                 "size" => 1.9,
            //                 "filledSize" => 0.00002,
            //                 "feeCurrency" => "BTC",
            //                 "feeAmount" => 1e-8,
            //                 "timestamp" => 1784890959551
            //             }
            //         ),
            //         "code" => 1,
            //         "msg" => "Success",
            //         "success" => true,
            //         "time" => 1786610160164
            //     }
            //
            $response = Async\await($this->privateGetSpotApiV4TradeTradeHistory($this->extend($request, $params)));
        } else {
            // the futures endpoint does not support a count parameter, the $limit is applied client-side
            $request = $this->omit($request, 'count');
            if ($market !== null) {
                $request['symbol'] = $this->futures_request_id($market);
            }
            //
            //     {
            //         "data" => array(
            //             {
            //                 "tradeId" => "1ad38104-6248-4a45-bc56-5fa9bf7f3868",
            //                 "orderId" => "8ad94105-8cce-4e01-86b8-2d0fb403db66",
            //                 "clOrderId" => "",
            //                 "positionId" => "BTC-PERP-USDT",
            //                 "orderSide" => "BUY",
            //                 "type" => 77,
            //                 "orderDetailType" => null,
            //                 "price" => 0,
            //                 "size" => 1,
            //                 "avgFilledPrice" => 60010,
            //                 "filledSize" => 1,
            //                 "triggerPrice" => 0,
            //                 "contractSize" => 0.00001,
            //                 "base" => "BTC",
            //                 "quote" => "USDT",
            //                 "symbol" => "BTC-PERP",
            //                 "wallet" => "BTC-PERP Isolated Wallet",
            //                 "feeCurrency" => "USDT",
            //                 "feeAmount" => 0.00012002,
            //                 "realizedPnl" => 0,
            //                 "total" => -0.00012002,
            //                 "serialId" => 375598162,
            //                 "timestamp" => 1784882344446
            //             }
            //         ),
            //         "code" => 1,
            //         "msg" => "Success",
            //         "success" => true,
            //         "time" => 1786610160164
            //     }
            //
            $response = Async\await($this->privateGetFuturesApiV3TradeTradeHistory($this->extend($request, $params)));
        }
        $rows = $this->safe_list($response, 'data');
        if ($rows === null) {
            $rows = $response;
        }
        return $this->parse_trades($rows, $market, $since, $limit);
    }

    public function fetch_order_trades(string $id, ?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order_trades(...))($id, $symbol, $since, $limit, $params);
    }

    private function do_fetch_order_trades(string $id, ?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch all the trades made from a single order
         *
         * @see https://btsecom.github.io/docs/spotV3_3/en/#query-user-trades-fills
         * @see https://btsecom.github.io/docs/futuresV2_3/en/#query-trades-fills-2
         *
         * @param {string} $id order $id
         * @param {string} [$symbol] unified market $symbol
         * @param {int} [$since] the earliest time in ms to fetch trades for
         * @param {int} [$limit] the maximum number of trades to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] client order $id, could be used instead of the order $id
         * @param {string} [$params->type] 'spot' or 'swap' or 'future', default is 'spot'
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?$id=trade-structure trade structures~
         */
        Async\await($this->load_markets());
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId === null) {
            if ($id === null) {
                throw new ArgumentsRequired($this->id . ' fetchOrderTrades() requires an $id argument or a $clientOrderId parameter');
            } else {
                $params = $this->extend($params, array( 'orderID' => $id ));
            }
        } else {
            $params = $this->extend($params, array( 'clOrderID' => $clientOrderId ));
        }
        return Async\await($this->fetch_my_trades($symbol, $since, $limit, $params));
    }

    public function parse_trade(array $trade, ?array $market = null): array {
        //
        // fetchTrades
        //     {
        //         "id" => 91151062,
        //         "timestamp" => 1786605669577,
        //         "price" => "1896.3291755587",
        //         "size" => "0.06",
        //         "quoteSize" => "113.7797505335",
        //         "side" => "BUY"
        //     }
        //
        // fetchMyTrades spot
        //     {
        //         "tradeId" => "4b4bd301-6f20-4e39-a682-ce4f9b8400a0",
        //         "orderId" => "2fa9678b-9945-47ce-9ffe-256dc7b4dd8c",
        //         "clOrderID" => "test spot $market buy",
        //         "username" => "romancuhari",
        //         "side" => "BUY",
        //         "orderType" => 77,
        //         "triggerType" => 0,
        //         "price" => 1952.05859608,
        //         "size" => 0.19520586,
        //         "filledPrice" => 1952.05859608,
        //         "filledSize" => 0.0001,
        //         "triggerPrice" => 0,
        //         "base" => "ETH",
        //         "quote" => "USDT",
        //         "symbol" => "ETH-USDT",
        //         "feeCurrency" => "ETH",
        //         "feeAmount" => 0.0000002,
        //         "wallet" => "SPOT@",
        //         "realizedPnl" => 0,
        //         "total" => 0,
        //         "serialId" => 49071052,
        //         "timestamp" => 1770814978685,
        //         "avgFilledPrice" => 1952.05859608
        //     }
        //
        // fetchMyTrades swap
        //     {
        //         "tradeId" => "b708489a-19d1-4be2-a6c2-f499f76aa176",
        //         "orderId" => "5c6a26db-8cfb-45c7-b25d-56927bc36795",
        //         "username" => "romancuhari",
        //         "side" => "BUY",
        //         "orderType" => 77,
        //         "triggerType" => null,
        //         "price" => 0,
        //         "size" => 1,
        //         "filledPrice" => 1956.59,
        //         "filledSize" => 1,
        //         "triggerPrice" => 0,
        //         "base" => "ETH",
        //         "quote" => "USDT",
        //         "symbol" => "ETH-PERP",
        //         "feeCurrency" => "USDT",
        //         "feeAmount" => 0.00010761,
        //         "wallet" => "CROSS@",
        //         "realizedPnl" => 0,
        //         "total" => -0.00010761,
        //         "serialId" => 50953296,
        //         "timestamp" => 1770821231984,
        //         "orderDetailType" => null,
        //         "contractSize" => 0.0001,
        //         "clOrderID" => "",
        //         "positionId" => "ETH-PERP-USDT",
        //         "avgFilledPrice" => 1956.59
        //     }
        //
        // the unified futures rows echo the short symbol form but carry the full
        // $market id in positionId, which resolves against the markets snapshot
        $marketId = $this->safe_string_2($trade, 'positionId', 'symbol');
        $market = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($trade, 'timestamp');
        $fee = null;
        $feeCost = $this->safe_number($trade, 'feeAmount');
        if ($feeCost !== null) {
            $fee = array(
                'cost' => $feeCost,
                'currency' => $this->safe_currency_code($this->safe_string($trade, 'feeCurrency')),
            );
        }
        return $this->safe_trade(array(
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $market['symbol'],
            'id' => $this->safe_string_n($trade, array( 'tradeId', 'serialId', 'id' )),
            'order' => $this->safe_string($trade, 'orderId'),
            'type' => $this->parse_order_type($this->safe_string_2($trade, 'orderType', 'type')),
            'side' => $this->safe_string_lower_2($trade, 'side', 'orderSide'),
            'takerOrMaker' => null,
            'price' => $this->safe_string_n($trade, array( 'filledPrice', 'avgFilledPrice', 'price' )),
            'amount' => $this->safe_string_2($trade, 'filledSize', 'size'),
            'cost' => null,
            'fee' => $fee,
        ), $market);
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_create_order(...))($symbol, $type, $side, $amount, $price, $params);
    }

    private function do_create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()) {
        /**
         * create a trade order
         *
         * @see https://btsecom.github.io/docs/spotV3_3/en/#create-new-order
         * @see https://btsecom.github.io/docs/futuresV2_3/en/#create-new-order
         * @see https://btsecom.github.io/docs/futuresV2_3/en/#create-new-algo-order
         *
         * @param {string} $symbol unified $symbol of the $market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of currency you want to trade in units of base currency
         * @param {float} [$price] the $price at which the order is to be fullfilled, in units of the quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] a unique id for the order
         * @param {bool} [$params->postOnly] if true, the order will only be posted to the order book and not executed immediately (default is false)
         * @param {string} [$params->timeInForce] 'GTC', 'IOC', 'FOK', 'PO', 'HALFMIN', 'FIVEMIN', 'HOUR', 'TWELVEHOUR', 'DAY', 'WEEK' or 'MONTH'
         * @param {float} [$params->triggerPrice] the $price that a trigger order is triggered at (same)
         * @param {float} [$params->stopLossPrice] the $price that a stop loss order is triggered at
         * @param {float} [$params->takeProfitPrice] the $price that a take profit order is triggered at
         * @param {string} [$params->triggerPriceType] 'INDEX_PRICE' or 'LAST_PRICE', default is 'LAST_PRICE'
         * @param {float} [$params->trailingAmount] the quote $amount to trail away from the current $market $price
         * @param {float} [$params->deviation] *PEG orders only* How much should the order $price deviate from index $price-> Value is in percentage and can range from -10 to 10
         * @param {float} [$params->stealth] *PEG orders only*  How many percent of the order is to be displayed on the orderbook
         * @param {float} [$params->stopPrice] *NB - It is NOT stopLossPrice or triggerPrice!!! OCO orders only* Mandatory when creating an OCO order. Indicates the stop $price
         * @param {bool} [$params->hedged] *contract markets only* true for hedged mode, false for one way mode, default is false
         * @param {string} [$params->marginMode] *contract markets only* 'cross' or 'isolated' (default is 'cross') - the exchange does not have cross/isolated margin modes but instead has 'ONE_WAY', 'HEDGE' and 'ISOLATED' position modes, so this param will be converted to the appropriate position mode
         * @param {string} [$params->positionMode] *contract markets only* 'ONE_WAY (default) or 'HEDGE or 'ISOLATED' (if not provided, it will be derived from marginMode and hedged $params)
         * @param {array} [$params->takeProfit] *contract markets only* *takeProfit object in $params* containing the triggerPrice at which the attached take profit order will be triggered (perpetual swap markets only)
         * @param {float} [$params->takeProfit.triggerPrice] *contract markets only* take profit trigger $price
         * @param {string} [$params->takeProfit.priceType] *contract markets only* 'markPrice' or 'lastPrice', default is 'markPrice'
         * @param {array} [$params->stopLoss] *contract markets only* *stopLoss object in $params* containing the triggerPrice at which the attached stop loss order will be triggered (perpetual swap markets only)
         * @param {float} [$params->stopLoss.triggerPrice] *contract markets only* stop loss trigger $price
         * @param {string} [$params->stopLoss.priceType] *contract markets only* 'markPrice' or 'lastPrice', default is 'markPrice'
         * @return {array} an ~@link https://docs.ccxt.com/?id=order-structure order structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        if ($market['spot'] === true) {
            return Async\await($this->create_spot_order($symbol, $type, $side, $amount, $price, $params));
        } else {
            return Async\await($this->create_contract_order($symbol, $type, $side, $amount, $price, $params));
        }
    }

    public function create_spot_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_create_spot_order(...))($symbol, $type, $side, $amount, $price, $params);
    }

    private function do_create_spot_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()) {
        /**
         * create a trade $order on spot $market
         *
         * @see https://docs.btse.com/spot/rest/place-$order
         * @see https://docs.btse.com/spot/rest/place-algo-$order
         *
         * @param {string} $symbol unified $symbol of the $market to create an $order in
         * @param {string} $type 'market', 'limit', 'OCO', 'PEG', 'TWAP' or 'TRAILING'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of you want to trade in units of the base currency
         * @param {float} [$price] the $price that the $order is to be fulfilled, in units of the quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] a unique id for the $order
         * @param {bool} [$params->postOnly] if true, the $order will only be posted to the $order book and not executed immediately, default is false
         * @param {string} [$params->timeInForce] 'GTC', 'IOC' or 'FOK'
         * @param {float} [$params->cost] *$market buy and trailing buy orders only* the quote quantity that can be used alternative for the $amount
         * @param {float} [$params->triggerPrice] the $price that a trigger $order is triggered at, same
         * @param {float} [$params->stopLossPrice] the $price that a stop loss $order is triggered at
         * @param {float} [$params->takeProfitPrice] the $price that a take profit $order is triggered at
         * @param {string} [$params->triggerPriceType] 'last', 'mark' or 'index', default is 'last'
         * @param {float} [$params->trailingAmount] the quote $amount to trail away from the current $market $price
         * @param {float} [$params->trailingPercent] the percent to trail away from the current $market $price
         * @param {float} [$params->deviation] *PEG orders only* how much should the $order $price deviate from the pegged $price, in percent from -10 to 10
         * @param {float} [$params->stealth] *PEG orders only* how many percent of the $order is to be displayed on the orderbook, from 1 to 100
         * @param {float} [$params->stopPrice] *NB - It is NOT $stopLossPrice or $triggerPrice!!! OCO orders only* the limit $price of the stop loss leg
         * @return {array} an ~@link https://docs.ccxt.com/?id=$order-structure $order structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $type = strtoupper($type);
        $upperSide = strtoupper($side);
        $request = array(
            'symbol' => $market['id'],
            'orderSide' => $upperSide,
        );
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $request['clOrderId'] = $clientOrderId;
            $params = $this->omit($params, 'clientOrderId');
        }
        $isMarketOrder = ($type === 'MARKET');
        $isLimitOrder = ($type === 'LIMIT');
        $postOnly = false;
        // exchange-specific $postOnly is the same unified one
        list($postOnly, $params) = $this->handle_post_only($isMarketOrder, $postOnly, $params); // this will remove PO from $params->timeInForce if present
        if ($postOnly) {
            $request['postOnly'] = true;
        }
        $timeInForce = $this->handle_time_in_force($params);
        if ($timeInForce !== null) {
            $request['timeInForce'] = $timeInForce;
        }
        $triggerPrice = $this->safe_string($params, 'triggerPrice');
        $takeProfitPrice = $this->safe_string($params, 'takeProfitPrice');
        $stopLossPrice = $this->safe_string($params, 'stopLossPrice');
        $isTriggerOrder = ($triggerPrice !== null) || ($takeProfitPrice !== null);
        $isStopLossOrder = ($stopLossPrice !== null);
        $isConditionalOrder = ($isTriggerOrder || $isStopLossOrder) && ($isMarketOrder || $isLimitOrder);
        $isAlgoOrder = $isConditionalOrder || (!$isMarketOrder && !$isLimitOrder);
        if ($isLimitOrder || ($type === 'PEG') || ($type === 'OCO')) {
            if ($price === null) {
                throw new InvalidOrder($this->id . ' createOrder() requires a $price argument for ' . $type . ' orders');
            }
        }
        // $market and trailing buys are denominated in the quote currency while
        // every other combination is denominated in the base currency, the
        // sizing rules are strict on both sides, verified live
        $needsQuoteSize = ($isMarketOrder || ($type === 'TRAILING')) && ($upperSide === 'BUY');
        if ($needsQuoteSize) {
            $quoteAmount = null;
            $createMarketBuyOrderRequiresPrice = true;
            list($createMarketBuyOrderRequiresPrice, $params) = $this->handle_option_and_params($params, 'createOrder', 'createMarketBuyOrderRequiresPrice', true);
            $cost = $this->safe_string($params, 'cost');
            $params = $this->omit($params, 'cost');
            if ($cost !== null) {
                $quoteAmount = $this->cost_to_precision($symbol, $cost);
            } elseif ($createMarketBuyOrderRequiresPrice) {
                if ($price === null) {
                    throw new InvalidOrder($this->id . ' createOrder() requires the $price argument for $market buy orders to calculate the total $cost to spend, alternatively set the $createMarketBuyOrderRequiresPrice option or param to false and pass the $cost to spend in the $amount argument');
                } else {
                    $amountString = $this->number_to_string($amount);
                    $priceString = $this->number_to_string($price);
                    $quoteAmount = $this->cost_to_precision($symbol, Precise::string_mul($amountString, $priceString));
                }
            } else {
                $quoteAmount = $this->cost_to_precision($symbol, $this->number_to_string($amount));
            }
            $request['quoteOrderSize'] = $quoteAmount;
        } else {
            $request['orderSize'] = $this->amount_to_precision($symbol, $amount);
        }
        $response = null;
        if (!$isAlgoOrder) {
            $request['orderType'] = $type;
            if ($isLimitOrder) {
                $request['orderPrice'] = $this->price_to_precision($symbol, $price);
            }
            //
            //     array(
            //         {
            //             "orderId" => "4eca2eb4-e6ad-4355-ae12-5ce757b105b3",
            //             "clOrderId" => "",
            //             "status" => 2,
            //             "market" => "BTC-USD",
            //             "type" => 76,
            //             "orderSide" => "BUY",
            //             "orderPrice" => 61024.1,
            //             "postOnly" => false,
            //             "timestamp" => 1784891308063,
            //             "orderDetailType" => null,
            //             "message" => null,
            //             "userQuoteCurrency" => "USD",
            //             "orderCurrency" => "base",
            //             "originalOrderBaseSize" => 0.00001,
            //             "originalOrderQuoteSize" => null,
            //             "currentOrderBaseSize" => 0.00001,
            //             "currentOrderQuoteSize" => null,
            //             "remainingOrderBaseSize" => 0.00001,
            //             "remainingOrderQuoteSize" => null,
            //             "filledBaseSize" => 0,
            //             "totalFilledBaseSize" => 0,
            //             "avgFilledPrice" => 0,
            //             "time_in_force" => "GTC"
            //         }
            //     )
            //
            $response = Async\await($this->privatePostSpotApiV4TradeOrders($this->extend($request, $params)));
        } else {
            if ($isConditionalOrder) {
                $request['orderType'] = 'CONDITIONAL';
                $triggerOrderType = null;
                $triggerPriceToSend = null;
                if ($isStopLossOrder) {
                    $triggerOrderType = 'STOP_LOSS';
                    $triggerPriceToSend = $stopLossPrice;
                } else {
                    $triggerOrderType = 'TAKE_PROFIT';
                    $triggerPriceToSend = $triggerPrice;
                    if ($triggerPriceToSend === null) {
                        $triggerPriceToSend = $takeProfitPrice;
                    }
                }
                if ($isLimitOrder) {
                    $triggerOrderType = $triggerOrderType . '_LIMIT';
                    $request['orderPrice'] = $this->price_to_precision($symbol, $price);
                }
                $request['triggerOrderType'] = $triggerOrderType;
                $request['triggerPrice'] = $this->price_to_precision($symbol, $triggerPriceToSend);
                $triggerPriceType = $this->safe_string($params, 'triggerPriceType', 'last');
                $request['triggerPriceType'] = $this->encode_trigger_price_type($triggerPriceType);
                $params = $this->omit($params, array( 'triggerPrice', 'takeProfitPrice', 'stopLossPrice', 'triggerPriceType' ));
            } else {
                $request['orderType'] = $type;
                if ($type === 'OCO') {
                    // the $price argument is the limit $price of the take profit leg,
                    // the $stopPrice param is the limit $price of the stop loss leg
                    // and the $triggerPrice param is where the stop loss leg fires
                    $request['takeProfitOrderPrice'] = $this->price_to_precision($symbol, $price);
                    $stopPrice = $this->safe_string($params, 'stopPrice');
                    if ($stopPrice !== null) {
                        $request['stopLossOrderPrice'] = $this->price_to_precision($symbol, $stopPrice);
                    }
                    if ($triggerPrice !== null) {
                        $request['stopLossTriggerPrice'] = $this->price_to_precision($symbol, $triggerPrice);
                    }
                    $triggerPriceType = $this->safe_string($params, 'triggerPriceType', 'last');
                    $request['stopLossTriggerPriceType'] = $this->encode_trigger_price_type($triggerPriceType);
                    $params = $this->omit($params, array( 'stopPrice', 'triggerPrice', 'triggerPriceType' ));
                } elseif ($type === 'PEG') {
                    // the required stealth and optional deviation $params pass through
                    $request['orderPrice'] = $this->price_to_precision($symbol, $price);
                } elseif ($type === 'TRAILING') {
                    $trailingAmount = $this->safe_string($params, 'trailingAmount');
                    $trailingPercent = $this->safe_string($params, 'trailingPercent');
                    if ($trailingAmount !== null) {
                        $request['trailValue'] = $this->price_to_precision($symbol, $trailingAmount);
                        $request['trailValueType'] = 'DISTANCE';
                    } elseif ($trailingPercent !== null) {
                        $request['trailValue'] = $trailingPercent;
                        $request['trailValueType'] = 'PERCENTAGE';
                    }
                    $triggerPriceType = $this->safe_string($params, 'triggerPriceType', 'last');
                    $request['triggerPriceType'] = $this->encode_trigger_price_type($triggerPriceType);
                    $params = $this->omit($params, array( 'trailingAmount', 'trailingPercent', 'triggerPriceType' ));
                }
                // TWAP orders require the timePeriod param which passes through
            }
            $response = Async\await($this->privatePostSpotApiV4TradeOrdersAlgo($this->extend($request, $params)));
        }
        $order = $this->safe_dict($response, 0, array());
        return $this->parse_order($order, $market);
    }

    public function create_contract_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_create_contract_order(...))($symbol, $type, $side, $amount, $price, $params);
    }

    private function do_create_contract_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()) {
        /**
         * create a trade $order on contract $market
         *
         * @see https://docs.btse.com/futures/rest/place-$order
         * @see https://docs.btse.com/futures/rest/place-algo-$order
         *
         * @param {string} $symbol unified $symbol of the $market to create an $order in
         * @param {string} $type 'market', 'limit', 'OCO', 'PEG', 'TWAP' or 'TRAILING'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of you want to trade in units of the base currency
         * @param {float} [$price] the $price that the $order is to be fulfilled, in units of the quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] a unique id for the $order
         * @param {bool} [$params->postOnly] if true, the $order will only be posted to the $order book and not executed immediately, default is false
         * @param {bool} [$params->reduceOnly] if true, the $order will only reduce a current position, not increase it, default is false
         * @param {string} [$params->timeInForce] 'GTC', 'IOC', 'FOK', 'PO', 'HALFSEC', 'HALFMIN', 'FIVEMIN', 'HOUR', 'TWELVEHOUR', 'DAY', 'WEEK' or 'MONTH'
         * @param {bool} [$params->hedged] true for $hedged mode, false for one way mode, default is false
         * @param {string} [$params->marginMode] 'cross' or 'isolated', default is 'cross' - the exchange does not have cross/isolated margin modes but instead has 'ONE_WAY', 'HEDGE' and 'ISOLATED' position modes, so this param will be converted to the appropriate position mode
         * @param {string} [$params->positionMode] 'ONE_WAY', 'HEDGE' or 'ISOLATED' - if not provided, it will be derived from the $marginMode and $hedged $params
         * @param {float} [$params->triggerPrice] the $price that a trigger $order is triggered at, same
         * @param {float} [$params->stopLossPrice] the $price that a stop loss $order is triggered at
         * @param {float} [$params->takeProfitPrice] the $price that a take profit $order is triggered at
         * @param {string} [$params->triggerPriceType] 'last', 'mark' or 'index', default is 'mark'
         * @param {float} [$params->trailingAmount] the quote $amount to trail away from the current $market $price
         * @param {float} [$params->trailingPercent] the percent to trail away from the current $market $price
         * @param {array} [$params->takeProfit] *$takeProfit object in $params* containing the $triggerPrice at which the attached take profit $order will be triggered
         * @param {float} [$params->takeProfit.triggerPrice] take profit trigger $price
         * @param {string} [$params->takeProfit.priceType] 'last', 'mark' or 'index', default is 'mark'
         * @param {array} [$params->stopLoss] *$stopLoss object in $params* containing the $triggerPrice at which the attached stop loss $order will be triggered
         * @param {float} [$params->stopLoss.triggerPrice] stop loss trigger $price
         * @param {string} [$params->stopLoss.priceType] 'last', 'mark' or 'index', default is 'mark'
         * @param {float} [$params->deviation] *PEG orders only* the offset applied to the pegged reference $price
         * @param {float} [$params->stealth] *PEG orders only* the portion of the $order size displayed on the book
         * @param {float} [$params->stopPrice] *NB - It is NOT the $stopLossPrice!!! OCO orders only* the limit $price of the stop loss leg
         * @return {array} an ~@link https://docs.ccxt.com/?id=$order-structure $order structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $type = strtoupper($type);
        $request = array(
            'symbol' => $this->futures_request_id($market),
            'orderSide' => strtoupper($side),
            'orderSize' => $this->amount_to_precision($symbol, $amount),
        );
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $request['clOrderId'] = $clientOrderId;
            $params = $this->omit($params, 'clientOrderId');
        }
        // handle $positionMode
        $positionMode = $this->safe_string($params, 'positionMode');
        // if $positionMode is provided, we will get it from $params and send it
        if ($positionMode === null) {
            $hedged = false;
            list($hedged, $params) = $this->handle_option_and_params($params, 'createOrder', 'hedged', $hedged);
            $marginMode = 'cross';
            list($marginMode, $params) = $this->handle_option_and_params($params, 'createOrder', 'marginMode', $marginMode);
            if ($marginMode === 'isolated') {
                if ($hedged) {
                    throw new BadRequest($this->id . ' createOrder() cannot use isolated margin with $hedged positions');
                }
                $request['positionMode'] = 'ISOLATED';
            } elseif ($hedged) {
                $request['positionMode'] = 'HEDGE';
            }
            // if not $hedged and not isolated, the default is ONE_WAY
        }
        $isMarketOrder = ($type === 'MARKET');
        $isLimitOrder = ($type === 'LIMIT');
        $postOnly = false;
        // exchange-specific $postOnly is the same unified one
        list($postOnly, $params) = $this->handle_post_only($isMarketOrder, $postOnly, $params); // this will remove PO from $params->timeInForce if present
        if ($postOnly) {
            $request['postOnly'] = true;
        }
        $timeInForce = $this->handle_time_in_force($params);
        if ($timeInForce !== null) {
            $request['timeInForce'] = $timeInForce;
        }
        $triggerPrice = $this->safe_string($params, 'triggerPrice');
        $takeProfitPrice = $this->safe_string($params, 'takeProfitPrice');
        $stopLossPrice = $this->safe_string($params, 'stopLossPrice');
        $isTriggerOrder = ($triggerPrice !== null) || ($takeProfitPrice !== null);
        $isStopLossOrder = ($stopLossPrice !== null);
        $isConditionalOrder = ($isTriggerOrder || $isStopLossOrder) && ($isMarketOrder || $isLimitOrder);
        $isAlgoOrder = $isConditionalOrder || (!$isMarketOrder && !$isLimitOrder);
        if ($isLimitOrder || ($type === 'OCO')) {
            if ($price === null) {
                throw new InvalidOrder($this->id . ' createOrder() requires a $price argument for ' . $type . ' orders');
            }
        }
        // here we handling with attached take profit and stop loss orders
        $takeProfit = $this->safe_dict($params, 'takeProfit');
        $stopLoss = $this->safe_dict($params, 'stopLoss');
        if (($takeProfit !== null) || ($stopLoss !== null)) {
            $takeProfitTriggerPrice = $this->safe_string($takeProfit, 'triggerPrice');
            $stopLossTriggerPrice = $this->safe_string($stopLoss, 'triggerPrice');
            if ($takeProfitTriggerPrice !== null) {
                $request['takeProfitTriggerPrice'] = $this->price_to_precision($symbol, $takeProfitTriggerPrice);
                $takeProfitTriggerPriceType = $this->safe_string($takeProfit, 'priceType');
                if ($takeProfitTriggerPriceType !== null) {
                    $request['takeProfitTriggerType'] = $this->encode_trigger_price_type($takeProfitTriggerPriceType);
                }
            }
            if ($stopLossTriggerPrice !== null) {
                $request['stopLossTriggerPrice'] = $this->price_to_precision($symbol, $stopLossTriggerPrice);
                $stopLossTriggerPriceType = $this->safe_string($stopLoss, 'priceType');
                if ($stopLossTriggerPriceType !== null) {
                    $request['stopLossTriggerType'] = $this->encode_trigger_price_type($stopLossTriggerPriceType);
                }
            }
            $params = $this->omit($params, array( 'takeProfit', 'stopLoss' ));
        }
        $response = null;
        if (!$isAlgoOrder) {
            $request['orderType'] = $type;
            if ($isLimitOrder) {
                $request['orderPrice'] = $this->price_to_precision($symbol, $price);
            }
            //
            //     {
            //         "status" => 2,
            //         "type" => 0,
            //         "symbol" => "BTC-PERP",
            //         "postOnly" => false,
            //         "orderSide" => "BUY",
            //         "orderId" => "0251ea47-88b5-48c0-aeb3-b38774fd1f90",
            //         "clOrderID" => "",
            //         "timestamp" => 1784882344361,
            //         "price" => 57009.5,
            //         "avgFilledPrice" => 0,
            //         "message" => null,
            //         "originalOrderSize" => 1,
            //         "currentOrderSize" => 1,
            //         "filledSize" => 0,
            //         "totalFilledSize" => 0,
            //         "remainingSize" => 1,
            //         "positionMode" => "ONE_WAY",
            //         "positionDirection" => null,
            //         "positionId" => "BTC-PERP-USDT",
            //         "timeInForce" => "GTC"
            //     }
            //
            $response = Async\await($this->privatePostFuturesApiV3TradeOrders($this->extend($request, $params)));
        } else {
            if ($isConditionalOrder) {
                // the futures conditional variant has no trigger direction field,
                // it takes a plain trigger $price with an optional limit $price
                $request['orderType'] = 'CONDITIONAL';
                $triggerPriceToSend = $triggerPrice;
                if ($triggerPriceToSend === null) {
                    $triggerPriceToSend = $takeProfitPrice;
                }
                if ($triggerPriceToSend === null) {
                    $triggerPriceToSend = $stopLossPrice;
                }
                $request['triggerPrice'] = $this->price_to_precision($symbol, $triggerPriceToSend);
                $triggerPriceType = $this->safe_string($params, 'triggerPriceType', 'mark');
                $request['triggerType'] = $this->encode_trigger_price_type($triggerPriceType);
                if ($isLimitOrder) {
                    $request['orderPrice'] = $this->price_to_precision($symbol, $price);
                }
                $params = $this->omit($params, array( 'triggerPrice', 'takeProfitPrice', 'stopLossPrice', 'triggerPriceType' ));
            } else {
                $request['orderType'] = $type;
                if ($type === 'OCO') {
                    // the $price argument is the limit $price of the take profit leg,
                    // the $stopPrice param is the limit $price of the stop loss leg
                    // and the $triggerPrice param is where the stop loss leg fires
                    $request['takeProfitOrderPrice'] = $this->price_to_precision($symbol, $price);
                    $stopPrice = $this->safe_string($params, 'stopPrice');
                    if ($stopPrice !== null) {
                        $request['stopLossOrderPrice'] = $this->price_to_precision($symbol, $stopPrice);
                    }
                    if ($triggerPrice !== null) {
                        $request['stopLossTriggerPrice'] = $this->price_to_precision($symbol, $triggerPrice);
                    }
                    $triggerPriceType = $this->safe_string($params, 'triggerPriceType', 'mark');
                    $request['stopLossTriggerType'] = $this->encode_trigger_price_type($triggerPriceType);
                    $params = $this->omit($params, array( 'stopPrice', 'triggerPrice', 'triggerPriceType' ));
                } elseif ($type === 'PEG') {
                    // the required deviation and stealth $params pass through, the
                    // optional $price argument becomes a worst-$price bound
                    if ($price !== null) {
                        $request['orderPrice'] = $this->price_to_precision($symbol, $price);
                    }
                } elseif ($type === 'TRAILING') {
                    $trailingAmount = $this->safe_string($params, 'trailingAmount');
                    $trailingPercent = $this->safe_string($params, 'trailingPercent');
                    if ($trailingAmount !== null) {
                        $request['trailValue'] = $this->price_to_precision($symbol, $trailingAmount);
                        $request['trailValueType'] = 'DISTANCE';
                    } elseif ($trailingPercent !== null) {
                        $request['trailValue'] = $trailingPercent;
                        $request['trailValueType'] = 'PERCENTAGE';
                    }
                    $triggerPriceType = $this->safe_string($params, 'triggerPriceType', 'mark');
                    $request['trailTriggerPriceType'] = $this->encode_trigger_price_type($triggerPriceType);
                    $params = $this->omit($params, array( 'trailingAmount', 'trailingPercent', 'triggerPriceType' ));
                }
                // TWAP orders require the timePeriod param which passes through
            }
            $response = Async\await($this->privatePostFuturesApiV3TradeOrdersAlgo($this->extend($request, $params)));
        }
        // the normal futures endpoint responds with a single $order dict, keep a
        // one element array guard in case a gateway wraps it
        $order = $response;
        if ((gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response)))) {
            $order = $this->safe_dict($response, 0, array());
        }
        return $this->parse_order($order, $market);
    }

    public function encode_trigger_price_type(?string $priceType) {
        $priceTypes = array(
            'last' => 'LAST_PRICE',
            'mark' => 'MARK_PRICE',
            'index' => 'INDEX_PRICE',
            'lastPrice' => 'LAST_PRICE',
            'markPrice' => 'MARK_PRICE',
            'indexPrice' => 'INDEX_PRICE',
        );
        return $this->safe_string($priceTypes, $priceType, $priceType);
    }

    public function fetch_open_order(string $id, ?string $symbol = null, $params = array()) {
        return Async\async(self::do_fetch_open_order(...))($id, $symbol, $params);
    }

    private function do_fetch_open_order(string $id, ?string $symbol = null, $params = array()) {
        /**
         * fetches information on an open $order made by the user
         *
         * @see https://docs.btse.com/spot/rest/get-$order
         * @see https://docs.btse.com/futures/rest/get-orders
         *
         * @param {string} $id the $order $id
         * @param {string} [$symbol] unified $symbol of the $market the $order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] a unique $id for the $order
         * @param {string} [$params->type] 'spot', 'swap' or 'future', default is 'spot'
         * @param {bool} [$params->includeCancelled] *contract markets only* if true, cancelled orders are included in the lookup
         * @return {array} An ~@link https://docs.ccxt.com/?$id=$order-structure $order structure~
         */
        Async\await($this->load_markets());
        $request = array();
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $request['clOrderId'] = $clientOrderId;
            $params = $this->omit($params, 'clientOrderId');
        } elseif ($id === null) {
            throw new ArgumentsRequired($this->id . ' fetchOpenOrder() requires an $id argument or a $clientOrderId parameter');
        } else {
            $request['orderId'] = $id;
        }
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $marketType = 'spot';
        list($marketType, $params) = $this->handle_market_type_and_params('fetchOrder', $market, $params, $marketType);
        $response = null;
        if ($marketType === 'spot') {
            $response = Async\await($this->privateGetSpotApiV4TradeOrder($this->extend($request, $params)));
        } else {
            // the futures endpoint doubles single $order lookup when an
            // $order $id is sent and responds with a bare array
            $response = Async\await($this->privateGetFuturesApiV3TradeOrders($this->extend($request, $params)));
        }
        // accept a bare $order dict, a data envelope and a one element array
        $order = $this->safe_value($response, 'data', $response);
        if ((gettype($order) === 'array' && array_keys($order) === array_keys(array_keys($order)))) {
            $order = $this->safe_dict($order, 0, array());
        }
        return $this->parse_order($order, $market);
    }

    public function edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array()) {
        return Async\async(self::do_edit_order(...))($id, $symbol, $type, $side, $amount, $price, $params);
    }

    private function do_edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array()) {
        /**
         * edit a trade $order
         *
         * @see https://docs.btse.com/spot/rest/amend-$order
         * @see https://docs.btse.com/futures/rest/amend-$order
         *
         * @param {string} $id $order $id
         * @param {string} $symbol unified $symbol of the $market to create an $order in
         * @param {string} $type 'market' or 'limit' (not used by btse)
         * @param {string} $side 'buy' or 'sell' (not used by btse)
         * @param {float} [$amount] how much of currency you want to trade in units of base currency
         * @param {float} [$price] the $price at which the $order is to be fulfilled, in units of the quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] a unique $id for the $order, required if $id is not provided
         * @param {float} [$params->triggerPrice] the $price that a trigger $order is triggered at
         * @param {bool} [$params->totalAmountMode] if true, the $amount is treated new total $order quantity including the already filled portion, default is false
         * @param {bool} [$params->slide] *contract markets only* if true and only the $price is amended, the $price slides to the best available $price
         * @return {array} an ~@link https://docs.ccxt.com/?$id=$order-structure $order structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array();
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $request['clOrderId'] = $clientOrderId;
            $params = $this->omit($params, 'clientOrderId');
        } elseif ($id === null) {
            throw new ArgumentsRequired($this->id . ' editOrder() requires an $id argument or a $clientOrderId parameter');
        } else {
            $request['orderId'] = $id;
        }
        $triggerPrice = $this->safe_string($params, 'triggerPrice');
        if ($triggerPrice !== null) {
            $request['triggerPrice'] = $this->price_to_precision($symbol, $triggerPrice);
            $params = $this->omit($params, 'triggerPrice');
        }
        if ($amount !== null) {
            $request['orderSize'] = $this->amount_to_precision($symbol, $amount);
        }
        if ($price !== null) {
            $request['orderPrice'] = $this->price_to_precision($symbol, $price);
        }
        $isSlide = $this->safe_bool($params, 'slide', false);
        if (($amount === null) && ($price === null) && ($triggerPrice === null) && ($isSlide !== true)) {
            throw new ArgumentsRequired($this->id . ' editOrder() requires an $amount argument, a $price argument or a $triggerPrice parameter');
        }
        $response = null;
        if ($market['spot'] === true) {
            $request['symbol'] = $market['id'];
            $response = Async\await($this->privatePutSpotApiV4TradeOrders($this->extend($request, $params)));
        } else {
            // the futures amend requires an explicit amendType discriminator
            // which can change the $price and size together or a single field
            $request['symbol'] = $this->futures_request_id($market);
            if ($triggerPrice !== null) {
                if (($amount !== null) || ($price !== null)) {
                    throw new BadRequest($this->id . ' editOrder() can not amend the trigger $price together with the $price or the $amount on contract markets');
                }
                $request['amendType'] = 'TRIGGER_PRICE';
            } elseif (($amount !== null) && ($price !== null)) {
                $request['amendType'] = 'ALL';
            } elseif ($amount !== null) {
                $request['amendType'] = 'SIZE';
            } else {
                $request['amendType'] = 'PRICE';
            }
            $response = Async\await($this->privatePutFuturesApiV3TradeOrders($this->extend($request, $params)));
        }
        $order = $this->safe_dict($response, 0, array());
        return $this->parse_order($order, $market);
    }

    public function cancel_order(string $id, ?string $symbol = null, $params = array()) {
        return Async\async(self::do_cancel_order(...))($id, $symbol, $params);
    }

    private function do_cancel_order(string $id, ?string $symbol = null, $params = array()) {
        /**
         *
         * @see https://docs.btse.com/spot/rest/cancel-$order
         * @see https://docs.btse.com/futures/rest/cancel-$order
         *
         * cancels an open $order
         * @param {string} $id $order $id
         * @param {string} $symbol unified $symbol of the $market the $order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] a unique $id for the $order, required if $id is not provided
         * @return {array} An ~@link https://docs.ccxt.com/?$id=$order-structure $order structure~
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' cancelOrder() requires a $symbol argument');
        }
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array();
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $request['clOrderId'] = $clientOrderId;
            $params = $this->omit($params, 'clientOrderId');
        } elseif ($id === null) {
            throw new ArgumentsRequired($this->id . ' cancelOrder() requires an $id argument or a $clientOrderId parameter');
        } else {
            $request['orderId'] = $id;
        }
        $response = null;
        if ($market['spot'] === true) {
            $request['symbol'] = $market['id'];
            $response = Async\await($this->privateDeleteSpotApiV4TradeOrders($this->extend($request, $params)));
        } else {
            //
            //     array(
            //         {
            //             "orderId" => "0251ea47-88b5-48c0-aeb3-b38774fd1f90",
            //             "clOrderId" => "",
            //             "symbol" => "BTC-PERP",
            //             "orderSide" => "BUY",
            //             "type" => 76,
            //             "orderPrice" => 56439.4,
            //             "orderSize" => 1,
            //             "filledSize" => 0,
            //             "status" => 6,
            //             "timestamp" => 1784882344500
            //         }
            //     )
            //
            $request['symbol'] = $this->futures_request_id($market);
            $response = Async\await($this->privateDeleteFuturesApiV3TradeOrders($this->extend($request, $params)));
        }
        $order = $this->safe_dict($response, 0, array());
        return $this->parse_order($order, $market);
    }

    public function cancel_all_orders(?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_all_orders(...))($symbol, $params);
    }

    private function do_cancel_all_orders(?string $symbol = null, $params = array()) {
        /**
         * cancel all open orders in a $market
         *
         * @see https://docs.btse.com/spot/rest/cancel-all-orders
         * @see https://btsecom.github.io/docs/futuresV2_3/en/#cancel-order
         *
         * @param {string} [$symbol] unified $market $symbol of the $market to cancel orders in, on spot markets omit it to cancel every open order across all pairs
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->type] 'spot', 'swap' or 'future', default is 'spot', used when the $symbol is omitted
         * @return {array[]} a list of ~@link https://docs.ccxt.com/?id=order-structure order structures~
         */
        Async\await($this->load_markets());
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $marketType = 'spot';
        list($marketType, $params) = $this->handle_market_type_and_params('cancelAllOrders', $market, $params, $marketType);
        $request = array();
        $response = null;
        if ($marketType === 'spot') {
            // the literal ALL value cancels every open order across all pairs
            $request['symbol'] = ($market !== null) ? $market['id'] : 'ALL';
            $response = Async\await($this->privateDeleteSpotApiV4TradeOrdersAll($this->extend($request, $params)));
        } else {
            if ($market === null) {
                throw new ArgumentsRequired($this->id . ' cancelAllOrders() requires a $symbol argument for contract markets');
            }
            // the unified futures api has no cancel all endpoint, the legacy
            // endpoint cancels every order for the $symbol when no order id is
            // sent, and it identifies contracts by the short $symbol form
            $request['symbol'] = $this->futures_request_id($market);
            $response = Async\await($this->privateDeleteFuturesApiV23Order($this->extend($request, $params)));
        }
        return $this->parse_orders($response, $market);
    }

    public function cancel_all_orders_after(?int $timeout, $params = array()) {
        return Async\async(self::do_cancel_all_orders_after(...))($timeout, $params);
    }

    private function do_cancel_all_orders_after(?int $timeout, $params = array()) {
        /**
         * dead man's switch, cancel all orders after the given $timeout
         *
         * @see https://docs.btse.com/spot/rest/cancel-all-after
         * @see https://docs.btse.com/futures/rest/cancel-all-after
         *
         * @param {number} $timeout time in milliseconds, 0 represents cancel the timer
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->type] 'spot', 'swap' or 'future', default is 'spot'
         * @return {array} the api result
         */
        Async\await($this->load_markets());
        $request = array();
        $response = null;
        $marketType = 'spot';
        list($marketType, $params) = $this->handle_market_type_and_params('cancelAllOrdersAfter', null, $params, $marketType);
        if ($marketType === 'spot') {
            $request['timeout'] = $timeout;
            $response = Async\await($this->privatePostSpotApiV4TradeOrdersCancelAllAfter($this->extend($request, $params)));
        } else {
            // the futures param is named timeoutMs and is required, zero disarms
            $request['timeoutMs'] = $timeout;
            $response = Async\await($this->privatePostFuturesApiV3TradeOrdersCancelAllAfter($this->extend($request, $params)));
        }
        return $response;
    }

    public function fetch_open_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_open_orders(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_open_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch all unfilled currently open orders
         *
         * @see https://docs.btse.com/spot/rest/get-orders
         * @see https://docs.btse.com/futures/rest/get-orders
         *
         * @param {string} [$symbol] unified $market $symbol
         * @param {int} [$since] the earliest time in ms to fetch open orders for, filtered client-side
         * @param {int} [$limit] the maximum number of open orders structures to retrieve, filtered client-side
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->type] 'spot', 'swap' or 'future', default is 'spot'
         * @return {Order[]} a list of ~@link https://docs.ccxt.com/?id=order-structure order structures~
         */
        Async\await($this->load_markets());
        $request = array();
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $marketType = 'spot';
        list($marketType, $params) = $this->handle_market_type_and_params('fetchOpenOrders', $market, $params, $marketType);
        $response = null;
        if ($marketType === 'spot') {
            if ($market !== null) {
                $request['symbol'] = $market['id'];
            }
            $response = Async\await($this->privateGetSpotApiV4TradeOrders($this->extend($request, $params)));
        } else {
            if ($market !== null) {
                $request['symbol'] = $this->futures_request_id($market);
            }
            $response = Async\await($this->privateGetFuturesApiV3TradeOrders($this->extend($request, $params)));
        }
        // the endpoints have no server side time filters, accept a bare array
        // and a data envelope and filter client-side
        $rows = $this->safe_list($response, 'data', $response);
        return $this->parse_orders($rows, $market, $since, $limit);
    }

    public function parse_order(array $order, ?array $market = null): array {
        //
        // createOrder - spot
        //     {
        //         "status" => 2,
        //         "symbol" => "ETH-USDT",
        //         "orderType" => 76,
        //         "price" => 1000,
        //         "side" => "BUY",
        //         "orderID" => "cde4fb37-2e2b-437e-a816-4b55b2e2b7c7",
        //         "timestamp" => 1770813053751,
        //         "triggerPrice" => 0,
        //         "stopPrice" => null,
        //         "trigger" => false,
        //         "message" => "",
        //         "clOrderID" => null,
        //         "stealth" => 1,
        //         "deviation" => 1,
        //         "postOnly" => false,
        //         "orderDetailType" => null,
        //         "originalOrderBaseSize" => 0.0001,
        //         "originalOrderQuoteSize" => null,
        //         "currentOrderBaseSize" => 0.0001,
        //         "currentOrderQuoteSize" => null,
        //         "remainingOrderBaseSize" => 0.0001,
        //         "remainingOrderQuoteSize" => null,
        //         "filledBaseSize" => 0,
        //         "totalFilledBaseSize" => 0,
        //         "orderCurrency" => "base",
        //         "avgFilledPrice" => 0,
        //         "time_in_force" => "GTC"
        //     }
        //
        // createOrder - swap
        //     {
        //         "status" => 4,
        //         "symbol" => "ETH-PERP",
        //         "orderType" => 77,
        //         "price" => 1956.59,
        //         "side" => "BUY",
        //         "orderID" => "5c6a26db-8cfb-45c7-b25d-56927bc36795",
        //         "timestamp" => 1770821231984,
        //         "triggerPrice" => 0,
        //         "trigger" => false,
        //         "deviation" => 100,
        //         "stealth" => 100,
        //         "message" => "",
        //         "avgFilledPrice" => 1956.59,
        //         "clOrderID" => "",
        //         "originalOrderSize" => 1,
        //         "currentOrderSize" => 1,
        //         "filledSize" => 1,
        //         "totalFilledSize" => 1,
        //         "remainingSize" => 0,
        //         "postOnly" => false,
        //         "orderDetailType" => null,
        //         "positionMode" => "ONE_WAY",
        //         "positionDirection" => null,
        //         "positionId" => "ETH-PERP-USDT",
        //         "time_in_force" => "GTC"
        //     }
        //
        $marketId = $this->safe_string_2($order, 'symbol', 'market');
        $market = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($order, 'timestamp');
        // open_orders rows carry no numeric $status - the state lives in
        // orderState (STATUS_ACTIVE / STATUS_INACTIVE), and time_in_force
        // is spelled timeInForce there (observed live), so both fall back
        $rawStatus = $this->safe_string_2($order, 'status', 'orderState');
        $rawType = $this->safe_string_2($order, 'orderType', 'type');
        $status = $this->parse_order_status($rawStatus);
        $orderType = $this->parse_order_type($rawType);
        if (($orderType === 'market') && ($status === 'open')) {
            // $market orders never rest on the book, the exchange reports the
            // partially filled code on them when a residual quote dust amount
            // cannot fill, observed live, such orders are finished
            $status = 'closed';
        }
        $rawTimeInForce = $this->safe_string_2($order, 'time_in_force', 'timeInForce');
        return $this->safe_order(array(
            'info' => $order,
            'id' => $this->safe_string_2($order, 'orderID', 'orderId'),
            'clientOrderId' => $this->safe_string_2($order, 'clOrderID', 'clOrderId'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => null,
            'lastUpdateTimestamp' => null,
            'status' => $status,
            'symbol' => $market['symbol'],
            'type' => $orderType,
            'timeInForce' => $this->parse_time_in_force($rawTimeInForce),
            'postOnly' => $this->safe_bool($order, 'postOnly'),
            'reduceOnly' => $this->safe_bool($order, 'reduceOnly'),
            'side' => $this->safe_string_lower_2($order, 'side', 'orderSide'),
            'price' => $this->safe_string_2($order, 'price', 'orderPrice'),
            'triggerPrice' => $this->omit_zero($this->safe_string_2($order, 'triggerOriginalPrice', 'triggerPrice')),
            'stopLossPrice' => null, // todo check
            'takeProfitPrice' => null, // todo check
            'amount' => $this->safe_string_n($order, array( 'currentOrderBaseSize', 'currentOrderSize', 'orderSize' )),
            'filled' => $this->safe_string_n($order, array( 'totalFilledBaseSize', 'totalFilledSize', 'filledSize' )),
            'remaining' => $this->safe_string_2($order, 'remainingOrderBaseSize', 'remainingSize'),
            'cost' => null,
            'trades' => null,
            'fee' => null,
            'average' => $this->omit_zero($this->safe_string_2($order, 'avgFilledPrice', 'averageFillPrice')),
        ), $market);
    }

    public function parse_order_status(?string $status) {
        $statuses = array(
            '2' => 'open', // Order Inserted
            '3' => 'closed', // Order Transacted
            '4' => 'closed', // Order Fully Transacted
            '5' => 'open', // Order Partially Transacted
            '6' => 'canceled', // Order Cancelled
            '7' => 'refunded', // Order Refunded
            '8' => 'rejected', // Insufficient Balance
            '9' => 'open', // Trigger Inserted
            '10' => 'open', // Trigger Activated
            '15' => 'rejected', // Order Rejected
            '16' => 'rejected', // Order Not Found
            '17' => 'rejected', // Request Failed
            '123' => 'open', // AMEND_ORDER = Order amended
            'STATUS_ACTIVE' => 'open', // open_orders orderState, observed live
            'STATUS_INACTIVE' => 'canceled', // open_orders orderState
            'ORDER_INSERTED' => 'open', // single order lookup orderState, observed live
            'ORDER_PARTIALLY_TRANSACTED' => 'open', // by analogy with the numeric codes
            'ORDER_FULLY_TRANSACTED' => 'closed', // by analogy with the numeric codes
            'ORDER_CANCELLED' => 'canceled', // by analogy with the numeric codes
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function parse_order_type(?string $type) {
        $types = array(
            // the unified futures place order response reports a degenerate 0
            // in the $type field regardless of the real order $type, observed
            // live, the value is deliberately left unmapped and passes through
            '76' => 'limit', // Limit order
            '77' => 'market', // Market order
            '80' => 'limit', // Peg/Algo order
        );
        return $this->safe_string($types, $type, $type);
    }

    public function parse_time_in_force(?string $timeInForce) {
        $values = array(
            'GTC' => 'GTC',
            'IOC' => 'IOC',
            'FOK' => 'FOK',
            'HALFSEC' => 'GTD',
            'HALFMIN' => 'GTD',
            'FIVEMIN' => 'GTD',
            'HOUR' => 'GTD',
            'TWELVEHOUR' => 'GTD',
            'DAY' => 'GTD',
            'WEEK' => 'GTD',
            'MONTH' => 'GTD',
        );
        return $this->safe_string($values, $timeInForce, $timeInForce);
    }

    public function fetch_trading_fees($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_trading_fees(...))($params);
    }

    private function do_fetch_trading_fees($params = array()) {
        /**
         * fetch the trading fees for multiple markets
         *
         * @see https://docs.btse.com/spot/rest/get-fees
         * @see https://btsecom.github.io/docs/futuresV2_3/en/#query-account-fee
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->type] 'spot', 'swap' or 'future' (default is 'spot')
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/?id=fee-structure fee structures~ indexed by $market symbols
         */
        Async\await($this->load_markets());
        $response = null;
        $marketType = 'spot';
        list($marketType, $params) = $this->handle_market_type_and_params('fetchTradingFees', null, $params, $marketType);
        if ($marketType === 'spot') {
            $response = Async\await($this->privateGetSpotApiV4TradeFees($params));
        } else {
            // the futures fees stay on the legacy endpoint, the unified futures
            // api has no fees route
            $response = Async\await($this->privateGetFuturesApiV23UserFees($params));
        }
        //
        //     array(
        //         {
        //             "symbol" => "FUSD-USD",
        //             "makerFee" => 0.002,
        //             "takerFee" => 0.002
        //         }
        //     )
        //
        $rows = $this->safe_list($response, 'data', $response);
        $responseList = $this->array_concat(array(), $rows);
        $result = array();
        for ($i = 0; $i < count($responseList); $i++) {
            $feeInfo = $responseList[$i];
            $marketId = $this->safe_string($feeInfo, 'symbol');
            $market = $this->safe_market($marketId);
            $symbol = $market['symbol'];
            $makerFee = $this->safe_number($feeInfo, 'makerFee');
            $takerFee = $this->safe_number($feeInfo, 'takerFee');
            $result[$symbol] = array(
                'info' => $feeInfo,
                'symbol' => $symbol,
                'maker' => $makerFee,
                'taker' => $takerFee,
                'percentage' => true,
                'tierBased' => true,
            );
        }
        return $result;
    }

    public function request_wallet_history_rows(string $methodName, array $historyTypes, ?string $code = null, ?int $since = null, ?int $limit = null, $params = array()) {
        return Async\async(self::do_request_wallet_history_rows(...))($methodName, $historyTypes, $code, $since, $limit, $params);
    }

    private function do_request_wallet_history_rows(string $methodName, array $historyTypes, ?string $code = null, ?int $since = null, ?int $limit = null, $params = array()) {
        // the helper always receives a non empty history $type list, the list is
        // rebuilt through safeList so the transpilers treat it array in
        // every runtime
        $typesList = $this->safe_list(array( 'types' => $historyTypes ), 'types', array());
        Async\await($this->load_markets());
        $walletType = $this->safe_string($params, 'walletType', 'SPOT');
        $request = array(
            'walletType' => $walletType,
        );
        // the endpoint applies a server side history $type filter sent
        // json encoded array in the query string, verified live
        $request['historyTypes'] = $this->json($typesList);
        $params = $this->omit($params, 'walletType');
        $currency = null;
        if ($code !== null) {
            $currency = $this->currency($code);
            $request['asset'] = $currency['id'];
        } elseif ($walletType === 'SPOT') {
            // the exchange rejects spot wallet history queries without an asset,
            // verified live, and omitting $walletType still defaults to spot
            throw new ArgumentsRequired($this->id . ' ' . $methodName . '() requires a $code argument for the spot wallet history');
        }
        if ($since !== null) {
            $request['startTime'] = $since;
        }
        if ($limit !== null) {
            $request['pageSize'] = $limit;
        }
        $until = null;
        list($until, $params) = $this->handle_option_and_params($params, $methodName, 'until');
        if ($until !== null) {
            $request['endTime'] = $until;
        }
        $response = Async\await($this->privateGetPublicApiWalletV1UserWalletHistory($this->extend($request, $params)));
        //
        //     {
        //         "code" => 1,
        //         "msg" => "Success",
        //         "time" => 1786624541092,
        //         "data" => array(
        //             {
        //                 "transactionTime" => 1786510157962,
        //                 "type" => "DEPOSIT",
        //                 "walletName" => "SPOT@",
        //                 "asset" => "USDT",
        //                 "netAmount" => "100",
        //                 "amount" => "100",
        //                 "transactionRef" => "2026081200000367",
        //                 "status" => "COMPLETED",
        //                 "description" => null,
        //                 "fees" => "0",
        //                 "cryptoNetwork" => "ERC20",
        //                 "toAddress" => "0x36bd7cbc486658c9777672fe742971bda65d5e6f",
        //                 "confirmTimes" => "(15/15)",
        //                 "txId" => "0xb4d88986d013f799d78e6232792c44b45dff1213a015171ddcf4adfcd283b3fd"
        //             }
        //         ),
        //         "success" => true
        //     }
        //
        $rawRows = $this->safe_list($response, 'data', $response);
        // the requested types are also filtered client side over both the legacy
        // and the unified enum vocabularies legacy endpoint ignored the
        // filter and returned the whole mixed ledger
        $allowed = array();
        for ($i = 0; $i < count($typesList); $i++) {
            $historyType = $typesList[$i];
            $allowed[$historyType] = true;
            $allowed[$this->capitalize(strtolower($historyType))] = true;
        }
        $rows = array();
        for ($i = 0; $i < count($rawRows); $i++) {
            $entry = $rawRows[$i];
            $type = $this->safe_string($entry, 'type', '');
            if (is_array($allowed) && array_key_exists($type ?? '', $allowed)) {
                $rows[] = $entry;
            }
        }
        return array( $rows, $currency );
    }

