    public function parse_transaction(array $transaction, ?array $currency = null): array {
        //
        //     {
        //         "username" => "user",
        //         "orderId" => "2026081200000367",
        //         "wallet" => "SPOT@",
        //         "currency" => "USDT",
        //         "type" => "Deposit",
        //         "amount" => 100,
        //         "fees" => 0,
        //         "description" => "",
        //         "timestamp" => 1786510157962,
        //         "status" => "PROCESSING",
        //         "txId" => "",
        //         "toAddress" => "0x0000000000000000000000000000000000000000",
        //         "currencyNetwork" => "",
        //         "sourceCurrency" => "USDT",
        //         "sourceAmount" => 0,
        //         "targetCurrency" => "",
        //         "targetAmount" => 0,
        //         "rate" => 0
        //     }
        //
        $currencyId = $this->safe_string_2($transaction, 'currency', 'asset');
        $code = $this->safe_currency_code($currencyId, $currency);
        $timestamp = $this->safe_integer_2($transaction, 'timestamp', 'transactionTime');
        $networkId = $this->safe_string_2($transaction, 'currencyNetwork', 'cryptoNetwork');
        return array(
            'info' => $transaction,
            'id' => $this->safe_string_2($transaction, 'orderId', 'transactionRef'),
            'txid' => $this->safe_string($transaction, 'txId'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'network' => $this->network_id_to_code($networkId, $code),
            'address' => $this->safe_string($transaction, 'toAddress'),
            'addressTo' => $this->safe_string($transaction, 'toAddress'),
            'addressFrom' => null,
            'tag' => null,
            'tagTo' => null,
            'tagFrom' => null,
            'type' => $this->parse_transaction_type($this->safe_string($transaction, 'type')),
            'amount' => $this->safe_number($transaction, 'amount'),
            'currency' => $code,
            'status' => $this->parse_transaction_status($this->safe_string($transaction, 'status')),
            'updated' => null,
            'internal' => null,
            'comment' => $this->safe_string($transaction, 'description'),
            'fee' => array(
                'currency' => $code,
                'cost' => $this->safe_number_2($transaction, 'fees', 'fee'),
            ),
        );
    }

    public function parse_transaction_type(?string $type): ?string {
