    public function fetch_ledger(?string $code = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ledger(...))($code, $since, $limit, $params);
    }

    private function do_fetch_ledger(?string $code = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch the history of changes, actions done by the user or operations that altered the balance of the user
         *
         * @see https://docs.btse.com/wallet/rest/get-user-wallet-history
         *
         * @param {string} [$code] unified $currency $code
         * @param {int} [$since] the earliest time in ms to fetch ledger entries for
         * @param {int} [$limit] the maximum number of ledger entry structures to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] the latest time in ms to fetch ledger entries for, excluded
         * @param {string} [$params->walletType] wallet to query, SPOT by default, ISOLATED requires $params->walletName
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=ledger ledger structures~
         */
        Async\await($this->load_markets());
        $request = array();
        $walletType = $this->safe_string($params, 'walletType', 'SPOT');
        $request['walletType'] = $walletType;
        $params = $this->omit($params, 'walletType');
        $currency = null;
        if ($code !== null) {
            $currency = $this->currency($code);
            $request['asset'] = $currency['id'];
        } elseif ($walletType === 'SPOT') {
            // the exchange rejects spot wallet history queries without an asset,
            // verified live, and omitting $walletType still defaults to spot
            throw new ArgumentsRequired($this->id . ' fetchLedger() requires a $code argument for the spot wallet history');
        }
        if ($since !== null) {
            $request['startTime'] = $since;
        }
        if ($limit !== null) {
            $request['pageSize'] = $limit;
        }
        $until = null;
        list($until, $params) = $this->handle_option_and_params($params, 'fetchLedger', 'until');
        if ($until !== null) {
            $request['endTime'] = $until;
        }
        $response = Async\await($this->privateGetPublicApiWalletV1UserWalletHistory($this->extend($request, $params)));
        //
        //     array(
        //         {
        //             "transactionTime" => 1786510157962,
        //             "type" => "DEPOSIT",
        //             "walletName" => "SPOT@",
        //             "asset" => "USDT",
        //             "netAmount" => "100",
        //             "amount" => "100",
        //             "transactionRef" => "2026081200000367",
        //             "status" => "PROCESSING",
        //             "description" => "",
        //             "fee" => "0",
        //             "cryptoNetwork" => "",
        //             "toAddress" => "0x0000000000000000000000000000000000000000",
        //             "confirmTimes" => "",
        //             "txId" => ""
        //         }
        //     )
        //
        $rows = $this->safe_list($response, 'data', $response);
        return $this->parse_ledger($rows, $currency, $since, $limit);
    }

