    public function fetch_trading_fee(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_trading_fee(...))($symbol, $params);
    }

    private function do_fetch_trading_fee(string $symbol, $params = array()) {
        /**
         * fetch the trading fees for a $market
         *
         * @see https://docs.btse.com/spot/rest/get-fees
         * @see https://btsecom.github.io/docs/futuresV2_3/en/#query-account-fee
         *
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=fee-structure fee structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        $response = null;
        if ($market['spot'] === true) {
            $response = Async\await($this->privateGetSpotApiV4TradeFees($this->extend($request, $params)));
        } else {
            // the futures fees stay on the legacy endpoint, the unified futures
            // api has no fees route
            $response = Async\await($this->privateGetFuturesApiV23UserFees($this->extend($request, $params)));
        }
        $rows = $this->safe_list($response, 'data', $response);
        $feeInfo = $this->safe_dict($rows, 0, array());
        $makerFee = $this->safe_number($feeInfo, 'makerFee');
        $takerFee = $this->safe_number($feeInfo, 'takerFee');
        return array(
            'info' => $feeInfo,
            'symbol' => $symbol,
            'maker' => $makerFee,
            'taker' => $takerFee,
            'percentage' => true,
            'tierBased' => true,
        );
    }

    public function fetch_positions(?array $symbols = null, $params = array()): PromiseInterface {
