            'symbol' => $this->futures_request_id($market),
        ), $params);
        return Async\await($this->fetch_positions(array( $symbol ), $params));
    }

    public function parse_position(array $position, ?array $market = null) {
        //
        //     {
        //         "marginType" => 91,
        //         "entryPrice" => 1968.78,
        //         "markPrice" => 1967.47829431,
        //         "symbol" => "ETH-PERP",
        //         "side" => "BUY",
        //         "orderValue" => 3.93495658,
        //         "settleWithAsset" => "USDT",
        //         "unrealizedProfitLoss" => -0.00260341,
        //         "totalMaintenanceMargin" => 0.0218963,
        //         "size" => 20,
        //         "liquidationPrice" => 0,
        //         "isolatedLeverage" => 25,
        //         "adlScoreBucket" => 1,
        //         "contractSize" => 0.0001,
        //         "liquidationInProgress" => false,
        //         "timestamp" => 1770880518034,
        //         "takeProfitOrder" => array(
        //             "orderId" => "18b4056a-59de-424a-843e-c2df5c9f7265",
        //             "side" => "SELL",
        //             "triggerPrice" => 2500,
        //             "triggerUseLastPrice" => false
        //         ),
        //         "stopLossOrder" => array(
        //             "orderId" => "e7ef1035-0773-446d-9a80-2de0e1de2c13",
        //             "side" => "SELL",
        //             "triggerPrice" => 1000,
        //             "triggerUseLastPrice" => false
        //         ),
        //         "positionMode" => "ONE_WAY",
        //         "positionDirection" => null,
        //         "positionId" => "ETH-PERP-USDT",
        //         "walletName" => "CROSS@",
        //         "currentLeverage" => 0.2,
        //         "minimumRequiredMargin" => 0
        //     }
        //
        // rows echo the short symbol form, while positionId carries the full $market
        // id, optionally suffixed with the isolated wallet discriminator after a pipe
        $marketId = $this->safe_string($position, 'positionId');
        if ($marketId !== null) {
            $parts = explode('|', $marketId);
            $marketId = $this->safe_string($parts, 0);
        } else {
            $marketId = $this->safe_string($position, 'symbol');
        }
        $market = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($position, 'timestamp');
        $marginType = $this->safe_string($position, 'marginType');
        $side = $this->safe_string_lower_2($position, 'positionDirection', 'side');
        $positionMode = $this->safe_string($position, 'positionMode');
        $hedged = ($positionMode === 'HEDGE') || ($positionMode === 'ISOLATED');
        $takeProfitOrder = $this->safe_dict($position, 'takeProfitOrder', array());
        $takeProfitPrice = $this->safe_string($takeProfitOrder, 'triggerPrice');
        $stopLossOrder = $this->safe_dict($position, 'stopLossOrder', array());
        $stopLossPrice = $this->safe_string($stopLossOrder, 'triggerPrice');
        return $this->safe_position(array(
            'info' => $position,
            'id' => $this->safe_string($position, 'positionId'),
            'symbol' => $market['symbol'],
            'entryPrice' => $this->parse_number($this->safe_string($position, 'entryPrice')),
            'markPrice' => $this->parse_number($this->safe_string($position, 'markPrice')),
            'lastPrice' => null,
            'takeProfitPrice' => $this->parse_number($takeProfitPrice),
            'stopLossPrice' => $this->parse_number($stopLossPrice),
            'notional' => $this->parse_number($this->safe_string_2($position, 'notionalValue', 'orderValue')),
            'collateral' => null,
            'unrealizedPnl' => $this->parse_number($this->safe_string($position, 'unrealizedProfitLoss')),
            'realizedPnl' => null,
            'side' => $this->parse_position_side($side),
            'contracts' => $this->parse_number($this->safe_string($position, 'size')),
            'contractSize' => $this->parse_number($this->safe_string($position, 'contractSize')),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastUpdateTimestamp' => null,
            'hedged' => $hedged,
            'maintenanceMargin' => $this->parse_number($this->safe_string($position, 'totalMaintenanceMargin')),
            'maintenanceMarginPercentage' => null,
            'initialMargin' => null,
            'initialMarginPercentage' => null,
            'leverage' => $this->parse_number($this->safe_string($position, 'currentLeverage')),
            'liquidationPrice' => $this->parse_number($this->safe_string($position, 'liquidationPrice')),
            'marginRatio' => null,
            'marginMode' => $this->parse_margin_mode_type($marginType),
            'percentage' => null,
        ));
    }

    public function parse_margin_mode_type(?string $marginMode) {
        $marginModes = array(
            '91' => 'cross',
            '92' => 'isolated',
            'CROSS' => 'cross',
            'ISOLATED' => 'isolated',
        );
        return $this->safe_string($marginModes, $marginMode, $marginMode);
    }

    public function parse_position_side(?string $side) {
        $sides = array(
            'buy' => 'long',
            'sell' => 'short',
        );
        return $this->safe_string($sides, $side, $side);
    }

    public function fetch_position_mode(?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_position_mode(...))($symbol, $params);
    }

    private function do_fetch_position_mode(?string $symbol = null, $params = array()) {
        /**
         * fetchs the position mode, $hedged or one way, $hedged for btse is set identically for all linear markets or all inverse markets
         *
         * @see https://docs.btse.com/futures/rest/get-position-mode
         *
         * @param {string} $symbol unified $symbol of the $market to fetch entry for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an object detailing whether the $market is in $hedged or one-way mode
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' fetchPositionMode() requires a $symbol argument');
        }
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $this->futures_request_id($market),
        );
        $response = Async\await($this->privateGetFuturesApiV3TradePositionMode($this->extend($request, $params)));
        //
        //     array(
        //         {
        //             "symbol" => "ETH-PERP",
        //             "positionMode" => "HEDGE"
        //         }
        //     )
        //
        $data = $this->safe_dict($response, 0, array());
        $positionMode = $this->safe_string($data, 'positionMode');
        $hedged = ($positionMode === 'HEDGE') || ($positionMode === 'ISOLATED');
        return array(
            'info' => $data,
            'hedged' => $hedged,
        );
    }

    public function set_position_mode(bool $hedged, ?string $symbol = null, $params = array()) {
        return Async\async(self::do_set_position_mode(...))($hedged, $symbol, $params);
    }

    private function do_set_position_mode(bool $hedged, ?string $symbol = null, $params = array()) {
        /**
         * NB!!! This method also sets margin mode to cross on btse. Set $hedged to true or false for a cross-margin $market->
         *
         * @see https://docs.btse.com/futures/rest/change-position-mode
         *
         * @param {bool} $hedged set to true to use dualSidePosition
         * @param {string} $symbol unified $symbol of the $market to set position mode for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} response from the exchange
         */
        // NB!!! This method also sets margin mode to cross on btse
        // btse do not have specific endpoint for marginMode
        // both marginMode and $positionMode are set and get with the same endpoints
        // it terms of btse $positionMode could be HEDGE, ONE_WAY or ISOLATED
        // ISOLATED $positionMode is always $hedged and multi-position
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' setPositionMode() requires a $symbol argument');
        }
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $positionMode = $hedged ? 'HEDGE' : 'ONE_WAY';
        $request = array(
            'symbol' => $this->futures_request_id($market),
            'positionMode' => $positionMode,
        );
        return Async\await($this->privatePostFuturesApiV3TradePositionMode($this->extend($request, $params)));
    }

    public function fetch_margin_mode(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_margin_mode(...))($symbol, $params);
    }

    private function do_fetch_margin_mode(string $symbol, $params = array()) {
        /**
         * fetches the margin mode of a specific $symbol
         *
         * @see https://docs.btse.com/futures/rest/get-leverage
         *
         * @param {string} $symbol unified $symbol of the $market the order was made in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=margin-mode-structure margin mode structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $this->futures_request_id($market),
        );
        $response = Async\await($this->privateGetFuturesApiV3TradeLeverage($this->extend($request, $params)));
        $data = $this->safe_dict($response, 0, array());
        return $this->parse_margin_mode($data, $market);
    }

    public function parse_margin_mode(array $marginMode, ?array $market = null): array {
        //
        //     {
        //         "symbol" => "ETH-PERP",
        //         "leverage" => 10,
        //         "marginMode" => "ISOLATED",
        //         "positionDirection" => "SHORT"
        //     }
        //
        $marketId = $this->safe_string($marginMode, 'symbol');
        $market = $this->safe_market($marketId, $market);
        $positionMode = $this->safe_string_lower($marginMode, 'marginMode');
        $marginModeValue = 'cross';
        if ($positionMode === 'isolated') {
            $marginModeValue = 'isolated';
        }
        return array(
            'info' => $marginMode,
            'symbol' => $market['symbol'],
            'marginMode' => $marginModeValue,
        );
    }

    public function set_margin_mode(string $marginMode, ?string $symbol = null, $params = array()) {
        return Async\async(self::do_set_margin_mode(...))($marginMode, $symbol, $params);
    }

    private function do_set_margin_mode(string $marginMode, ?string $symbol = null, $params = array()) {
        /**
         * set margin mode to 'cross' or 'isolated'
         *
         * @see https://docs.btse.com/futures/rest/change-position-mode
         *
         * @param {string} $marginMode 'cross' or 'isolated'
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {bool} [$params->hedged] set to true to use dualSidePosition, required for setting $marginMode to cross on btse
         * @return {array} response from the exchange
         */
        // btse do not have specific endpoint for $marginMode
        // both $marginMode and $positionMode are set and get with the same endpoints
        // it terms of btse $positionMode could be HEDGE, ONE_WAY or ISOLATED
        // ISOLATED $positionMode is always $hedged and multi-position
        // we use $params->hedged to define the $positionMode when $marginMode is cross
        // and warn user if the $params are not correct for the $marginMode being set
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' setMarginMode() requires a $symbol argument');
        }
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $marginMode = strtolower($marginMode);
        $positionMode = 'ONE_WAY';
        if (($marginMode !== 'cross') && ($marginMode !== 'isolated')) {
            throw new BadRequest($this->id . ' setMarginMode() $marginMode argument should be either cross or isolated');
        }
        $hedged = $this->safe_bool($params, 'hedged');
        if ($marginMode === 'cross') {
            if (!(is_array($params) && array_key_exists('hedged' ?? '', $params))) {
                throw new ArgumentsRequired($this->id . ' setMarginMode() requires a $hedged parameter for cross margin mode');
            } elseif ($hedged === true) {
                $positionMode = 'HEDGE';
            }
        } elseif ((is_array($params) && array_key_exists('hedged' ?? '', $params)) && ($hedged !== true)) {
            throw new BadRequest($this->id . ' setMarginMode() $hedged parameter cannot be false for isolated margin mode');
        } else {
            $positionMode = 'ISOLATED';
        }
        $params = $this->omit($params, 'hedged');
        $request = array(
            'symbol' => $this->futures_request_id($market),
            'positionMode' => $positionMode,
        );
        return Async\await($this->privatePostFuturesApiV3TradePositionMode($this->extend($request, $params)));
    }

    public function close_position(string $symbol, ?string $side = null, $params = array()): PromiseInterface {
        return Async\async(self::do_close_position(...))($symbol, $side, $params);
    }

    private function do_close_position(string $symbol, ?string $side = null, $params = array()) {
        /**
         * closes an open position for a $market
         *
         * @see https://docs.btse.com/futures/rest/close-position/
         *
         * @param {string} $symbol unified CCXT $market $symbol
         * @param {string} [$side] not used by btse
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->positionId] the id of the position to close, mandatory
         * @param {string} [$params->type] 'limit' or 'market' (default is 'market')
         * @param {float} [$params->price] required if $params->type is 'limit'
         * @param {bool} [$params->postOnly] true if the $order should be post only
         * @return {array} An ~@link https://docs.ccxt.com/?id=$order-structure $order structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $positionId = $this->safe_string($params, 'positionId');
        if ($positionId === null) {
            throw new ArgumentsRequired($this->id . ' closePosition() requires a $positionId parameter');
        }
        $request = array(
            'symbol' => $this->futures_request_id($market),
        );
        $type = 'market';
        list($type, $params) = $this->handle_option_and_params($params, 'closePosition', 'type', $type);
        $type = strtoupper($type);
        $request['orderType'] = $type;
        if ($type === 'LIMIT') {
            $price = $this->safe_string($params, 'price');
            if ($price === null) {
                throw new ArgumentsRequired($this->id . ' closePosition() requires a $price parameter for limit orders');
            }
            $request['orderPrice'] = $this->price_to_precision($symbol, $price);
            $params = $this->omit($params, 'price');
        }
        $response = Async\await($this->privateDeleteFuturesApiV3TradePositions($this->extend($request, $params)));
        $order = $this->safe_dict($response, 0);
        if ($order === null) {
            $order = $response;
        }
        return $this->parse_order($order, $market);
    }

    public function fetch_leverage(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_leverage(...))($symbol, $params);
    }

    private function do_fetch_leverage(string $symbol, $params = array()) {
        /**
         * fetch the leverage for a $market
         *
         * @see https://docs.btse.com/futures/rest/get-leverage
         *
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=leverage-structure leverage structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $this->futures_request_id($market),
        );
        $response = Async\await($this->privateGetFuturesApiV3TradeLeverage($this->extend($request, $params)));
        //
        //     array(
        //         array(
        //             "symbol" => "ETH-PERP",
        //             "leverage" => 10,
        //             "marginMode" => "ISOLATED",
        //             "positionDirection" => "LONG"
        //         ),
        //         {
        //             "symbol" => "ETH-PERP",
        //             "leverage" => 10,
        //             "marginMode" => "ISOLATED",
        //             "positionDirection" => "SHORT"
        //         }
        //     )
        //
        $safeResponse = array();
        if ((gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response)))) {
            $safeResponse = $response;
        }
        $result = array(
            'info' => $response,
            'symbol' => $symbol,
        );
        $longLeverage = null;
        $shortLeverage = null;
        $marginMode = null;
        for ($i = 0; $i < count($safeResponse); $i++) {
            $entrty = $safeResponse[$i];
            $leverageValue = $this->safe_integer($entrty, 'leverage');
            $positionDirection = $this->safe_string($entrty, 'positionDirection');
            $marginMode = $this->safe_string_lower($entrty, 'marginMode');
            if ($positionDirection === 'LONG') {
                $longLeverage = $leverageValue;
            } elseif ($positionDirection === 'SHORT') {
                $shortLeverage = $leverageValue;
            } elseif ($positionDirection === null) {
                $longLeverage = $leverageValue;
                $shortLeverage = $leverageValue;
            }
        }
        $result['marginMode'] = $marginMode;
        $result['longLeverage'] = $longLeverage;
        $result['shortLeverage'] = $shortLeverage;
        return $result;
    }

    public function set_leverage(int $leverage, ?string $symbol = null, $params = array()) {
        return Async\async(self::do_set_leverage(...))($leverage, $symbol, $params);
    }

    private function do_set_leverage(int $leverage, ?string $symbol = null, $params = array()) {
        /**
         * set the level of $leverage for a $market
         *
         * @see https://docs.btse.com/futures/rest/change-$leverage
         *
         * @param {float} $leverage the rate of $leverage
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->positionMode] ONE_WAY or HEDGE, defaults to ONE_WAY on the exchange side when omitted
         * @param {string} [$params->positionDirection] LONG or SHORT, identifies the side to update in hedge mode
         * @param {string} [$params->positionId] existing position id to update, disambiguates the target position in hedge mode
         * @return {array} $response from the exchange
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' setLeverage() requires a $symbol argument');
        }
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $this->futures_request_id($market),
            'leverage' => $leverage, // a value of 0 requests the maximum cross $leverage per the documentation
        );
        // the endpoint defaults to the ISOLATED bucket when $marginMode is omitted,
        // verified live - a bare call on a cross account silently changes the
        // isolated $leverage only, so the unified $marginMode param is translated here
        $marginMode = null;
        list($marginMode, $params) = $this->handle_margin_mode_and_params('setLeverage', $params);
        if ($marginMode !== null) {
            $request['marginMode'] = strtoupper($marginMode);
        }
        $response = Async\await($this->privatePostFuturesApiV3TradeLeverage($this->extend($request, $params)));
        return $response;
    }

    public function handle_errors(int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if (($response === null) || ($response === null)) {
            return null; // fallback to default error handler
        }
        //
        // spot
        //
        //     array("code":10002,"msg":"UNAUTHORIZED => Authentication Failed","time":1770477230034,"data":null,"success":false)
        //     array("code":51523,"msg":"BADREQUEST => Insufficient wallet balance","time":1770814875493,"data":null,"success":false)
        //
        // futures
        //
        //     array("status":400,"errorCode":-2,"message":"symbol parameter is mandatory","extraData":null)
        //     array("status":400,"errorCode":-7,"message":"Authenticate failed","extraData":null)
        //
        $success = $this->safe_bool($response, 'success', true);
        if ($success !== true) {
            $spotErrorCode = $this->safe_string($response, 'code');
            $spotMessage = $this->safe_string($response, 'msg');
            $feedback = $this->id . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $spotErrorCode, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $spotMessage, $feedback);
            throw new ExchangeError($feedback);
        }
        $errorCode = $this->safe_string($response, 'errorCode');
        if ($errorCode !== null) {
            $message = $this->safe_string($response, 'message');
            $feedback = $this->id . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $errorCode, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $message, $feedback);
            throw new ExchangeError($feedback);
        }
        //
        // futures order and leverage endpoints reply with HTTP 200 and encode failures in a numeric $status field, per the API Enum section of the docs
        //
        //     array("symbol":"ETH-PERP","timestamp":1770892916507,"status":135,"type":93,"message":"array(\"msgKey\":\"trade.error.invalid.position_id\",\"params\":[\"ETH-PERP-USDT\"] ,\"default_msg\":\"User is in ISOLATE_HEDGE in market => ETH-PERP-USDT, but positionId is empty in the request.\")")
        //
        // $success statuses such ORDER_INSERTED, 4 ORDER_FULLY_TRANSACTED, 5 ORDER_PARTIALLY_TRANSACTED, 6 ORDER_CANCELLED, 9 TRIGGER_INSERTED, 10 TRIGGER_ACTIVATED and 20 SUCCESS fall through without matching
        //
        // the legacy error envelope documented on the error codes page carries
        // the numeric api $status enum in the $code field beside the http $status
        //
        //     array("status":400,"error":"Bad Request","code":301,"message":"Invalid order size")
        //
        $legacyErrorText = $this->safe_string($response, 'error');
        $legacyEnumCode = $this->safe_string($response, 'code');
        if (($legacyErrorText !== null) && ($legacyEnumCode !== null)) {
            $legacyMessage = $this->safe_string($response, 'message');
            $feedback = $this->id . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $legacyEnumCode, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $legacyMessage, $feedback);
            throw new ExchangeError($feedback);
        }
        $rows = array();
        if ((gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response)))) {
            $rows = $response;
        } else {
            $rows = array( $response );
        }
        for ($i = 0; $i < count($rows); $i++) {
            $row = $rows[$i];
            $status = $this->safe_string($row, 'status');
            if ($status !== null) {
                $message = $this->safe_string($row, 'message');
                $embedded = $this->parse_json($message);
                if ($embedded !== null) {
                    $message = $this->safe_string($embedded, 'default_msg', $message);
                }
                $feedback = $this->id . ' ' . $body;
                $this->throw_exactly_matched_exception($this->exceptions['exact'], $status, $feedback);
                $this->throw_broadly_matched_exception($this->exceptions['broad'], $message, $feedback);
            }
        }
        return null;
    }

    public function sign(mixed $path, mixed $api = 'public', $method = 'GET', $params = array(), mixed $headers = null, mixed $body = null) {
        $baseUrl = $this->urls['api'][$api];
        $url = $baseUrl . '/' . $this->implode_params($path, $params);
        $query = $this->omit($params, $this->extract_params($path));
        // the futures v3 trading $api reads DELETE $params from a signed json
        // $body like its POST and PUT counterparts, while the spot v4 and the
        // legacy apis keep DELETE $params in the $query string, verified live
        // in both directions
        $isBodyDelete = ($method === 'DELETE') && (str_starts_with($path, 'futures/api/v3/') === true);
        $queryString = '';
        if ((($method === 'GET') || ($method === 'DELETE')) && !$isBodyDelete) {
            if (count($query) > 0) {
                $queryString = $this->urlencode($query);
                $url .= '?' . $queryString;
            }
        }
        if ($api === 'private') {
            $this->check_required_credentials();
            $nonce = $this->nonce();
            $bodyString = $this->json($query);
            if ((($method === 'GET') || ($method === 'DELETE')) && !$isBodyDelete) {
                $bodyString = '';
            } else {
                $body = $bodyString;
            }
            // the signed urlpath is the $path relative to the base $url of the product, the
            // spot and futures apis of every generation mount under /spot and /futures and
            // sign the /api/v... remainder, while the public-$api wallet, otc and markets
            // endpoints mount on the bare host and sign the full $path with the leading slash
            $signPath = null;
            if (str_starts_with($path, 'public-api/') === true) {
                $signPath = '/' . $path;
            } else {
                $signPath = $this->clean_path($path);
            }
            $payload = $signPath . (string) $nonce . $bodyString;
            $signature = $this->hmac($this->encode($payload), $this->encode($this->secret), 'sha384');
            $headers = array(
                'request-api' => $this->apiKey,
                'request-nonce' => (string) $nonce,
                'request-sign' => $signature,
                'Content-Type' => 'application/json',
                'BROKER-ID' => 'ccxt',
            );
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function futures_request_id(mixed $market) {
        // the futures v3 trading api identifies contracts by the short trade-currency
        // form, for example RAVE-PERP instead of the RAVE-PERP-USDT $market id, read
        // from the raw $market info so that cached markets resolve it
        return $this->safe_string($market['info'], 'tradeCurrency', $market['id']);
    }

    public function clean_path(string $path) {
        $result = str_replace('spot', '', $path);
        $result = str_replace('futures', '', $result);
        $result = str_replace('otc', '', $result);
        return $result;
    }

    public function nonce() {
        return $this->milliseconds() - $this->options['timeDifference'];
    }
}
